INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_37091f5a305c928c', 'course_computer_vision', 'exe_859716bb3c48a094', '30, 50 and 190', 1, 'Right: 20 - 50 = -30, and `convertScaleAbs` takes the **absolute value**, so -30 is stored as 30. The other two fit: 50 and 190.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_290e770d4612fa47', 'course_computer_vision', 'exe_859716bb3c48a094', '0, 50 and 190', 0, 'This is what you might expect from saturation, but `convertScaleAbs` takes the absolute value **before** it keeps results between 0 and 255, so -30 becomes 30, not 0.', 2);
