INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_6333337648b035e4', 'course_computer_vision', 'exe_e990711e1559dd53', 'reference_solution', 'img = [[30, 90, 150],
