INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_a458ca765de0f8eb', 'course_computer_vision', 'exe_e990711e1559dd53', 'accepted_solution', 'img = [[30, 90, 150],
