INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_065ebbec4e1602bc', 'course_computer_vision', 'exe_cbbfb62cdb150cc7', 'reference_solution', 'min_distance = int(input())
count = int(input())
kept = []
for i in range(count):
    parts = input().split()
    x = int(parts[0])
    y = int(parts[1])
    too_close = False
    for kx, ky in kept:
        d = ((x - kx) ** 2 + (y - ky) ** 2) ** 0.5
        if d < min_distance:
            too_close = True
    if not too_close:
        kept.append((x, y))
print(len(kept), "corners kept")
for kx, ky in kept:
    print(kx, ky)', 1);
