INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_8537c6a5377c9307', 'course_computer_vision', 'top_fa0401151f7ab2ba', 'les_442fa32aab5eb1bb', 'cvd-correct-threshold-rule', 'correct_code', 'Fix Canny''s two-threshold rule', 'The program decides, for one pixel, whether Canny keeps it as an edge. It reads the strength of the change, the low and high thresholds, and `yes` or `no` for whether the pixel connects to a sure edge. One word on the `elif` line is wrong. Fix it.', 'strength = int(input())
low = int(input())
high = int(input())
connected = input()
if strength > high:
    print("edge")
elif strength > low or connected == "yes":
    print("edge")
else:
    print("not an edge")', 'python', '- stronger than `high`: `edge`
- between `low` and `high`: `edge` only if it connects to a sure edge, otherwise `not an edge`
- weaker than `low`: `not an edge`, even when it connects', 'A medium change is kept only when it is above `low` **and** connects to a sure edge, so the two conditions must be joined with `and`. With `or`, every change above `low` became an edge (third test), and even weak changes became edges whenever they touched one (fourth test).', 'medium', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
