INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_7b956918d19d8835', 'course_computer_vision', 'exe_b53094b239c17a47', 'A square in the middle of the clear sky', 1, 'Right: a flat region looks the same everywhere, so any square of sky would match.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_e901aab203156a8c', 'course_computer_vision', 'exe_b53094b239c17a47', 'The corner of a window', 0, 'Corners are the **easiest**: the image changes in every direction around them, so their position is unique.', 2);
