INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_b53094b239c17a47', '/courses/computer-vision/exercises/cvd-flat-hardest', 'The hardest place to find again', 'You mark one small square in a photo and try to find exactly the same spot in a second photo of the same street. Which spot is the hardest to find again?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_2e7cd48a4577a667', 'course_computer_vision', 'top_fa0401151f7ab2ba', 'les_442fa32aab5eb1bb', 'cvd-reduce-texture-edges', 'mcq', 'Too many edges in the grass', '`cv2.Canny(gray, 50, 100)` fills the grass and the road''s stones with short marks. Which changes give **fewer of these texture edges**? Pick **all** that do.', NULL, NULL, '', 'Texture is many small, weak changes in brightness. Two ways remove them: **make them weaker** (blur first) or **demand stronger changes** (raise the thresholds, keeping `high` about 2 to 3 times `low`). On `street.png`, going from (50, 100) to (150, 250) cut the edge pixels from 8.9% to 3.8%.', 'medium', 'auto', '{"multiple":true,"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
