INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_ff97cfd778db462a', 'course_computer_vision', 'exe_2e7cd48a4577a667', 'Raise both thresholds, for example to `(150, 250)`.', 1, 'Right: higher thresholds keep only the strong changes, such as outlines.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_0e0deaab68001221', 'course_computer_vision', 'exe_2e7cd48a4577a667', 'Blur the image first, for example with `cv2.GaussianBlur(gray, (5, 5), 0)`.', 1, 'Right: blurring weakens small, fine changes before Canny measures them.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_40b30fcef243b696', 'course_computer_vision', 'exe_2e7cd48a4577a667', 'Lower both thresholds, for example to `(20, 40)`.', 0, 'Lower thresholds count **weaker** changes as edges, so you get even more texture.', 3);
