INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_4987c01fccacfbf4', 'course_computer_vision', 'top_fa0401151f7ab2ba', 'les_442fa32aab5eb1bb', 'cvd-threshold-rule', 'mcq', 'Between the two thresholds', 'With `cv2.Canny(gray, 100, 200)`, the brightness change at a pixel measures **150**. Is the pixel marked as an edge?', NULL, NULL, '', '| Change at a pixel | Result |
|---|---|
| stronger than `high` (200) | an edge, for sure |
| between `low` and `high` | an edge **only if** it connects to a sure edge |
| weaker than `low` (100) | not an edge |', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
