INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_c0961b7cde7ac103', '/courses/computer-vision/exercises/cvd-trace-canny-step', 'Canny on a two-tone image', 'img is a 50 × 50 grayscale image: the left half is 120 and the right half is 220, so there is one straight, vertical edge down the middle. flat is the same size, all 120. What exactly does the program print? import cv2 import numpy as np img = np.full((50, 50), 120, dtype=np.uint8) img[:, 25:] = 220 edges = cv2.Canny(img, 100, 200) print(edges.shape) print(np.unique(edges)) print(np.count_nonzero(edges)) flat = np.full((50, 50), 120, dtype=np.uint8) print(np.count_nonzero(cv2.Canny(flat, 100, 200)))');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_f97c7c7fb685c035', 'course_computer_vision', 'top_fa0401151f7ab2ba', 'les_442fa32aab5eb1bb', 'cvd-value-edge-percent', 'trace', 'What share of the pixels are edges?', 'Canny marked 18,144 pixels as edges in a 960 × 540 image. What is the value of `percent` **when the last line runs**? Type the number only.', 'edge_pixels = 18144
total = 960 * 540
percent = round(edge_pixels / total * 100, 1)
print("Measured")', 'python', '', '960 × 540 = 518,400 pixels. 18,144 ÷ 518,400 = 0.035, and × 100 that is **3.5** %. This is the same measure as `np.count_nonzero(edges) / edges.size * 100` in the lecture''s experiment.', 'easy', 'auto', '{"ask":"value","compare":"normalize_whitespace","caseSensitive":true,"verify":{"language":"python","code":"edge_pixels = 18144\ntotal = 960 * 540\npercent = round(edge_pixels / total * 100, 1)\nprint(percent)"}}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
