INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_e1d97370952fa6c9', 'course_computer_vision', 'exe_14bad551d38d7b79', 'reference_solution', 'values = []
for text in input().split():
    values.append(int(text))
lo = min(values)
hi = max(values)
