print(result)', 1);
INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_f213127d64182a24', 'course_computer_vision', 'exe_14bad551d38d7b79', 'accepted_solution', 'values = []
for text in input().split():
    values.append(int(text))
lo = min(values)
hi = max(values)
result = []
for v in values:
    result.append(round(255 * (v - lo) / (hi - lo)))
print(result)', 2);
