INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_dc591af6ffb38d88', 'course_computer_vision', 'exe_5b09460f2b969de0', 'grayscale → resize → denoise → equalize', 1, 'Right: one channel and fewer pixels make every later step faster, and the noise is gone before the values are spread.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a430fd16096bd0d0', 'course_computer_vision', 'exe_5b09460f2b969de0', 'equalize → denoise → resize → grayscale', 0, '`equalizeHist` needs grayscale, so it can''t come first. And equalizing first would make the noise stronger.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c37f1c1a69e0a054', 'course_computer_vision', 'exe_5b09460f2b969de0', 'grayscale → equalize → denoise → resize', 0, 'Equalizing before denoising spreads the noise apart too, making it harder to remove. Resizing last also wastes work.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_f71562fa7feaa5d3', 'course_computer_vision', 'exe_5b09460f2b969de0', 'resize → equalize → grayscale → denoise', 0, 'Equalization needs a grayscale image, so grayscale must come before it.', 4);
