INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_e62664f6c298011e', 'course_computer_vision', 'top_ed5ce0c87ecbac13', 'les_9e2de7522d4f2b45', 'cve-histogram-shape', 'mcq', 'Reading a histogram', 'A grayscale image''s histogram has all its bars **bunched in a narrow band in the middle**, between about 110 and 150. How does the image look?', NULL, NULL, '', 'A histogram counts how many pixels have each value from 0 to 255. A narrow band means only a few greys are used, all close together. Histogram equalization (`cv2.equalizeHist`) is made for exactly this case: it spreads the values over the whole range.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
