INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_9136e117c9c470ce', '/courses/computer-vision/exercises/cve-trace-equalize-range', 'The range before and after equalizing', 'foggy is a tiny grayscale image whose nine values are squeezed between 100 and 175, like the foggy street in the lecture. What exactly does the program print? import cv2 import numpy as np foggy = np.array([[100, 110, 120], [130, 140, 150], [160, 170, 175]], dtype=np.uint8) equalized = cv2.equalizeHist(foggy) print(foggy.min(), foggy.max()) print(equalized.min(), equalized.max())');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_084a34993d092725', 'course_computer_vision', 'top_ed5ce0c87ecbac13', 'les_112ebfc8b5df2c05', 'cve-trace-wrong-variable', 'trace', 'One wrong variable in a pipeline', '`img` is a black colour image the same size as `street.png`. Look carefully at which variable each line uses. What exactly does the program print?', 'import cv2
import numpy as np

img = np.zeros((540, 960, 3), dtype=np.uint8)
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
resized = cv2.resize(gray, (640, 480))
blur = cv2.GaussianBlur(gray, (5, 5), 0)
enhanced = cv2.equalizeHist(blur)
print(resized.shape)
print(enhanced.shape)', 'python', '', 'Line 7 should blur `resized`, but it blurs `gray`. So the resized image is made and then never used, and the final result is still 960 × 540. No error appears; only the shape shows the mistake. In a pipeline, each step must take the **previous** step''s result.', 'medium', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
