INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_084a34993d092725', '/courses/computer-vision/exercises/cve-trace-wrong-variable', 'One wrong variable in a pipeline', 'img is a black colour image the same size as street.png . Look carefully at which variable each line uses. What exactly does the program print? import cv2 import numpy as np img = np.zeros((540, 960, 3), dtype=np.uint8) gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) resized = cv2.resize(gray, (640, 480)) blur = cv2.GaussianBlur(gray, (5, 5), 0) enhanced = cv2.equalizeHist(blur) print(resized.shape) print(enhanced.shape)');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_33e0da4f6a98411c', 'course_computer_vision', 'top_f8a91881121beec6', 'les_4fe7de1a048935ac', 'cvf-centre-six', 'mcq', 'A kernel with 6 in the centre', 'A student changes the centre of the sharpening kernel from 5 to 6. What happens when this kernel is applied with `cv2.filter2D`?', 'kernel = np.array([[0, -1, 0], [-1, 6, -1], [0, -1, 0]])', 'python', '', 'In a flat area every neighbour equals the centre, so the new value is the centre times the **sum of the kernel''s numbers**. With 5 and four −1s the sum is 1, so flat areas keep their value. With 6 the sum is 2, so every flat area doubles in brightness (and anything above 127 ends up at 255).', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
