INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_0be1ef3a023cae5d', 'course_computer_vision', 'exe_33e0da4f6a98411c', 'A flat grey area of 100 becomes 200: the whole image gets brighter, not only the edges.', 1, 'Right: 6 × 100 − 4 × 100 = 200. The numbers now add up to 2, not 1.', 1);
