INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_565cca1290e73038', '/courses/computer-vision/exercises/cvf-correct-clip', 'Fix the 0 to 255 limit', 'The program reads a pixel and its four neighbours on one line (centre, above, below, left, right), applies the sharpening kernel and keeps the result between 0 and 255. It prints 0 for almost everything. Fix it. The program prints 5 × centre − above − below − left − right , but a result below 0 becomes 0 and a result above 255 becomes 255. values = input().split() centre = int(values[0]) above = int(values[1]) below = int(values[2]) left = int(values[3]) right = int(values[4]) new = 5 * centre - above - below - left - right new = min(0, max(255, new)) print(new)');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_7dbcbdc68552b85b', 'course_computer_vision', 'top_f8a91881121beec6', 'les_4fe7de1a048935ac', 'cvf-denoise-first', 'mcq', 'Sharpen a noisy frame?', 'A camera frame is a little blurry **and** a little noisy. What should the program do?', NULL, NULL, '', 'Sharpening makes each pixel **less** like its neighbours. A noisy speck is exactly that: a pixel that differs from its neighbours. So the rule is **denoise first, sharpen second**, for example a light `cv2.GaussianBlur` or `cv2.medianBlur` and then `cv2.filter2D` with the sharpening kernel.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
