INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_22d5e8f2bf0002aa', 'course_computer_vision', 'top_f8a91881121beec6', 'les_4fe7de1a048935ac', 'cvf-filter2d-minus-one', 'mcq', 'The -1 in filter2D', 'What does the `-1` mean in `cv2.filter2D(img, -1, kernel)`?', NULL, NULL, '', 'The second argument of `cv2.filter2D` is the **depth** (the number type) of the result. `-1` means "the same as the input". For a normal `uint8` image, results below 0 become 0 and results above 255 become 255, so the sharpened image can be shown and saved like the original.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
