INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_b24c52b3fc5f0fa2', '/courses/computer-vision/exercises/cvf-value-sharpen-pixel', 'One sharpened pixel', 'The program applies the sharpening kernel to one pixel by hand. What is the value of new when the last line runs ? Type the number only. centre = 90 above = 90 below = 90 left = 50 right = 90 new = 5 * centre - above - below - left - right new = max(0, min(255, new)) print("Pixel done")');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_c54d83f9a17913c5', 'course_computer_vision', 'top_5bb64696cc8a4154', 'les_4cfff55b88f41741', 'cvi-camera-only-captures', 'mcq', 'Is a camera computer vision?', 'A doorbell camera records video to a memory card all day. Nobody''s program looks at the video. Is this computer vision?', NULL, NULL, '', 'Computer vision is about **extracting useful information** from images and videos:

**Image → computer vision system → understanding or a decision**

Recording alone has no understanding step and no decision.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
