INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_511d80d1b8d9ce99', 'course_computer_vision', 'exe_c54d83f9a17913c5', 'No: it only captures images. Computer vision is the processing that gets information out of them.', 1, 'Right: a camera is only step 1. It becomes computer vision when a program, for example, notices that a person is at the door.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_213c7c1b7b02d350', 'course_computer_vision', 'exe_c54d83f9a17913c5', 'Yes: anything with a camera is computer vision.', 0, 'A camera only records light. That is the most common misunderstanding about computer vision.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_76eb3e7a3e08fefe', 'course_computer_vision', 'exe_c54d83f9a17913c5', 'Yes, because the video is stored as numbers.', 0, 'Every digital image is stored as numbers. Computer vision is what a program **does** with those numbers.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4e9dc03e1eaf2a98', 'course_computer_vision', 'exe_c54d83f9a17913c5', 'No, because computer vision only works on single photos, not videos.', 0, 'Computer vision works on both images and videos (many images in a row).', 4);
