INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_c54d83f9a17913c5', '/courses/computer-vision/exercises/cvi-camera-only-captures', 'Is a camera computer vision?', 'A doorbell camera records video to a memory card all day. Nobody''s program looks at the video. Is this computer vision?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_15df8b45d4be4ece', 'course_computer_vision', 'top_5bb64696cc8a4154', 'les_d210cceea941f3d2', 'cvi-classification-no-where', 'mcq', 'What a classifier doesn''t say', 'An image classification model looks at a dashcam photo and answers `car`. What does this answer **not** tell you?', NULL, NULL, '', 'Classification asks "what is this a picture of?". It gives no location. Detection adds a box for each object, and segmentation finds each object''s exact pixels.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
