INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_99bfeb8892faf6f5', 'course_computer_vision', 'exe_15df8b45d4be4ece', 'Where the car is in the picture', 1, 'Right: classification gives one label for the whole image. Finding where needs detection or segmentation.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c8610550c257f782', 'course_computer_vision', 'exe_15df8b45d4be4ece', 'What the picture shows', 0, 'That is exactly what a classifier gives: one label for the whole picture.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_65ac4e3edf3d2e2f', 'course_computer_vision', 'exe_15df8b45d4be4ece', 'That the program looked at the picture''s pixels', 0, 'Every model works on the pixel values; that''s all it receives.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_3fb18736302517ee', 'course_computer_vision', 'exe_15df8b45d4be4ece', 'Anything: a classifier always gives a box too', 0, 'Boxes come from object detection, not classification.', 4);
