INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_15df8b45d4be4ece', '/courses/computer-vision/exercises/cvi-classification-no-where', 'What a classifier doesn''t say', 'An image classification model looks at a dashcam photo and answers car . What does this answer not tell you?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_61d437076e7b3e43', 'course_computer_vision', 'top_5bb64696cc8a4154', 'les_4cfff55b88f41741', 'cvi-correct-count-numbers', 'correct_code', 'How many numbers does an image store?', 'The program reads an image''s width and height and prints how many numbers the computer stores for it: first as a grayscale image (one number per pixel), then as a colour image (three numbers per pixel). One line is wrong. Fix it.', 'width = int(input())
height = int(input())
gray = width + height
color = gray * 3
print(gray, color)', 'python', 'The user types the width, then the height. For a 640 × 480 image the program prints `307200 921600`.', 'An image is a grid: `height` rows of `width` pixels each, so it has **width × height** pixels. A grayscale image stores one number per pixel, and a colour image three.

The third test passes even with the bug, because 2 + 2 and 2 × 2 are both 4. That is why a program needs more than one test.', 'easy', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
