INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_6afd938426bc622a', 'course_computer_vision', 'exe_4f7390368df38a85', 'Object detection', 1, 'Right: detection says **what** each object is and **where** it is, with a box.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_0fcf9fb3720417f8', 'course_computer_vision', 'exe_4f7390368df38a85', 'Image classification', 0, 'Classification gives **one label** for the whole image, and no location.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_3fe6ac8724a81d98', 'course_computer_vision', 'exe_4f7390368df38a85', 'Image segmentation', 0, 'Segmentation labels **every pixel**, which gives each person''s exact outline, not a box.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_5528e9f50cb0471b', 'course_computer_vision', 'exe_4f7390368df38a85', 'Face recognition', 0, 'Face recognition says **who** a face belongs to. Here we only need to find people.', 4);
