INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_4f7390368df38a85', '/courses/computer-vision/exercises/cvi-detection-boxes', 'A box around every customer', 'A shop camera must draw a box around every customer in the picture and write "person" next to each box. Which computer vision task is this?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_6603ba63089a471e', 'course_computer_vision', 'top_5bb64696cc8a4154', 'les_d210cceea941f3d2', 'cvi-feature-extraction-step', 'mcq', 'Which step is this?', 'A program takes a frame that has already been resized and smoothed, and finds the **edges** along the lane lines. Which pipeline step is it doing?', NULL, NULL, '', 'Edges and corners are **features**: simple patterns that later steps build on. The step before (processing) makes them easier to find; the step after (analysis) works out what they mean.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
