INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b5f9d3ca7780a245', 'course_computer_vision', 'exe_6603ba63089a471e', 'Feature extraction', 1, 'Right: finding simple, useful patterns such as edges and corners is step 3.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d37d5b712ac6fb48', 'course_computer_vision', 'exe_6603ba63089a471e', 'Image processing', 0, 'Processing (step 2) only prepares the image: resizing and smoothing, which were already done here.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_447c43427296fa66', 'course_computer_vision', 'exe_6603ba63089a471e', 'Analysis', 0, 'Analysis (step 4) **interprets** the edges, for example deciding "these edges are the lane".', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_ba677eb84f80a56c', 'course_computer_vision', 'exe_6603ba63089a471e', 'Decision', 0, 'The decision (step 5) acts on the result, for example "keep in lane".', 4);
