INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_6603ba63089a471e', '/courses/computer-vision/exercises/cvi-feature-extraction-step', 'Which step is this?', 'A program takes a frame that has already been resized and smoothed, and finds the edges along the lane lines. Which pipeline step is it doing?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_8117b29fdad3f801', 'course_computer_vision', 'top_5bb64696cc8a4154', 'les_d210cceea941f3d2', 'cvi-pipeline-order', 'mcq', 'The five steps in order', 'Which list shows the steps of the basic computer vision pipeline **in the right order**?', NULL, NULL, '', '| Step | Example: a car''s camera |
|---|---|
| 1. Image acquisition | one frame of the road ahead |
| 2. Image processing | make it the right size, reduce noise |
| 3. Feature extraction | edges, corners, lane-line pixels |
| 4. Analysis | "these edges are the lane" |
| 5. Decision | keep in lane, slow down |', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
