INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_db74f0fc67819ff4', 'course_computer_vision', 'exe_8117b29fdad3f801', 'acquisition → processing → feature extraction → analysis → decision', 1, 'Right: capture the image, prepare it, find simple patterns, interpret them, then act.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_f5e59beaa3d7835a', 'course_computer_vision', 'exe_8117b29fdad3f801', 'acquisition → feature extraction → processing → analysis → decision', 0, 'Processing comes **before** feature extraction: the image is cleaned and resized first, so the edges and corners found later are reliable.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_2906898061ea6ab7', 'course_computer_vision', 'exe_8117b29fdad3f801', 'processing → acquisition → analysis → feature extraction → decision', 0, 'There is nothing to process before an image has been captured.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_ddbbd9c58f9a5c02', 'course_computer_vision', 'exe_8117b29fdad3f801', 'acquisition → processing → analysis → decision → feature extraction', 0, 'The decision is always last: it acts on what the earlier steps found.', 4);
