INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_8117b29fdad3f801', '/courses/computer-vision/exercises/cvi-pipeline-order', 'The five steps in order', 'Which list shows the steps of the basic computer vision pipeline in the right order ?');
