INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_2b4451126d997cd2', 'course_computer_vision', 'top_5bb64696cc8a4154', 'les_4cfff55b88f41741', 'cvi-trace-window-corner', 'trace', 'Nine pixels as a List of rows', 'These are the 9 pixel values at the corner of a window in `street.png`, stored as a List of rows. What exactly does the program print?', 'patch = [[181, 181, 181],
         [181, 65, 65],
         [181, 65, 65]]
print(len(patch), "rows,", len(patch[0]), "columns")
print("top-left:", patch[0][0])
print("centre:", patch[1][1])', 'python', '', 'To the computer, the corner of the window is just numbers: **181** for the light wall and **65** for the dark glass. `patch[0][0]` is the top-left value, on the wall. `patch[1][1]` is the middle of the 3 × 3 grid, which is already inside the dark window. Nothing in the numbers says "window": a program has to find that pattern.', 'easy', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
