INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_9302c0b5f463253a', 'course_computer_vision', 'exe_23af825526df068d', 'reference_solution', 'video = input().split()
next_index = 0
processed = 0
while True:
    if next_index < len(video):
        ret, frame = True, video[next_index]
        next_index = next_index + 1
    else:
        ret, frame = False, None
    if not ret:
        break
    print("edges of", frame)
    processed = processed + 1
print("frames processed:", processed)', 1);
INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_f8842e46dd3be49e', 'course_computer_vision', 'exe_23af825526df068d', 'accepted_solution', 'video = input().split()
next_index = 0
processed = 0
while True:
    if next_index < len(video):
        ret, frame = True, video[next_index]
        next_index = next_index + 1
    else:
        ret, frame = False, None
    if ret == False:
        break
    print("edges of", frame)
    processed = processed + 1
print("frames processed:", processed)', 2);
