INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_589d920c43cf9e96', 'course_computer_vision', 'top_f0b6f4af7c3d4192', 'les_c2b34d76e1b701c6', 'cvj-edge-ai', 'mcq', 'What edge AI means', 'The project vehicle uses **edge AI**. What does that mean?', NULL, NULL, '', '**Edge AI: AI processing happens close to where the data is generated.** On the vehicle, the Jetson (a small computer with a GPU) runs the computer vision on every frame, so the vehicle can react quickly and still works with no network.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
