INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_9f45877ac4ea54ff', 'course_computer_vision', 'top_f0b6f4af7c3d4192', 'les_44febf2b824a078c', 'cvj-ret-false', 'mcq', 'When is ret False?', 'In `ret, frame = cap.read()`, when is `ret` **False**?', NULL, NULL, '', '`cap.read()` gives back two values: `ret` says whether reading worked, and `frame` is the image. When nothing could be read, `ret` is `False` and `frame` is `None`. Without `if not ret: break`, the next line, `cv2.resize(frame, …)`, would fail on `None`.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
