INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_9f45877ac4ea54ff', '/courses/computer-vision/exercises/cvj-ret-false', 'When is ret False?', 'In ret, frame = cap.read() , when is ret False ?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_cd48d5b460385d66', 'course_computer_vision', 'top_f0b6f4af7c3d4192', 'les_44febf2b824a078c', 'cvj-trace-black-frame', 'trace', 'One black frame through the pipeline', 'A camera gives a completely black 1280 × 720 frame (the lens cap is on). It goes through the project pipeline once. What exactly does the program print?', 'import cv2
import numpy as np

frame = np.zeros((720, 1280, 3), dtype=np.uint8)
resized = cv2.resize(frame, (640, 480))
gray = cv2.cvtColor(resized, cv2.COLOR_BGR2GRAY)
blur = cv2.GaussianBlur(gray, (5, 5), 0)
edges = cv2.Canny(blur, 50, 150)
print(frame.shape)
print(gray.shape)
print(edges.shape, np.count_nonzero(edges))', 'python', '', 'Every camera size becomes 640 × 480 after the resize, which is why the pipeline resizes first: the later steps always get the same size. Grayscale removes the channel number, and Canny gives back an image of the same size.

A black frame has no change in brightness anywhere, so Canny finds **0** edge pixels. Note that `ret` would still be `True` for this frame: the camera worked, it just saw nothing.', 'medium', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
