INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_1552d7ac991b25f8', '/courses/computer-vision/exercises/cvj-trace-fps', 'Can the loop keep up?', 'Three versions of a team''s loop take 20, 40 and 50 milliseconds per frame. The camera delivers 30 frames per second. What exactly does the program print? for ms in [20, 40, 50]: fps = 1000 / ms if fps >= 30: print(ms, "ms:", int(fps), "FPS, keeps up") else: print(ms, "ms:", int(fps), "FPS, too slow")');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_2966b9c117d11376', 'course_computer_vision', 'top_f0b6f4af7c3d4192', 'les_44febf2b824a078c', 'cvj-waitkey-q', 'mcq', 'The q key test', 'What does this line do inside the camera loop?', 'if cv2.waitKey(1) & 0xFF == ord(''q''):
    break', 'python', '', '`cv2.waitKey(1)` does two jobs in the loop: it gives OpenCV a moment to **draw the windows**, and it reports which key, if any, was pressed. Comparing it with `ord(''q'')` makes **q** the exit key. After the loop, `cap.release()` frees the camera and `cv2.destroyAllWindows()` closes the windows.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
