INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_93fbed762d23e44a', 'course_computer_vision', 'exe_2966b9c117d11376', 'It waits 1 millisecond for a key, lets the windows refresh, and leaves the loop if the key was q.', 1, 'Right: `ord(''q'')` is the code of the letter q, and `& 0xFF` keeps the last byte of the key code.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cc7134a2beaf7f52', 'course_computer_vision', 'exe_2966b9c117d11376', 'It waits until the user presses q, then shows the next frame.', 0, '`waitKey(1)` waits only 1 ms. With `waitKey(0)` the video would stop on every frame.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_8cb9a8a7f2460923', 'course_computer_vision', 'exe_2966b9c117d11376', 'It stops the program after 1 frame.', 0, 'The `break` only happens when q was pressed.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_913bc9cf8590e8df', 'course_computer_vision', 'exe_2966b9c117d11376', 'It only checks for q; the windows refresh by themselves.', 0, 'OpenCV draws its windows only while `waitKey` runs. Without it they stay grey.', 4);
