INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_d63c98f879c8935a', 'course_computer_vision', 'top_98c70721c3dc932b', 'les_98c70721c3dc932b', 'cvm-best-30', 'mcq', 'Which matches are drawn?', 'Which matches does this code draw?', 'matches = sorted(matches, key=lambda x: x.distance)
result = cv2.drawMatches(img1, kp1, img2, kp2, matches[:30], None)', 'python', '', 'The distance counts differing bits, so **smaller is better**. `sorted(…, key=lambda x: x.distance)` orders the matches from most to least similar, and `matches[:30]` keeps the best 30. Drawing only the best few keeps the picture readable; hundreds of lines would hide everything.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
