INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_a0d403400aee0259', '/courses/computer-vision/exercises/cvm-correct-good-count', 'Fix the good-match counter', 'The program reads a limit, then the distances of some matches on one line, and counts the good matches: those with a distance below the limit. One comparison is wrong. Fix it. A match is good when its distance is smaller than the limit. For a limit of 10 and the distances 1 7 9 33 39 41 52 58 66 90 , three are good. limit = int(input()) distances = input().split() good = 0 for text in distances: if int(text) > limit: good = good + 1 print(good, "good matches")');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_f09aa2bdd8b579b2', 'course_computer_vision', 'top_98c70721c3dc932b', 'les_98c70721c3dc932b', 'cvm-crosscheck', 'mcq', 'What crossCheck keeps', 'Feature 4 in image A has feature 9 in image B as its best match. But feature 9 in image B has feature 2 in image A as **its** best match. With `crossCheck=True`, what happens to the pair A4–B9?', NULL, NULL, '', '`crossCheck=True` keeps a match only if the two features **choose each other**. One-sided matches, like A4 → B9 here, are often wrong matches between patches that only look a bit alike, so dropping them makes the result more reliable.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
