INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_e808d876ee3fcc28', 'course_computer_vision', 'top_98c70721c3dc932b', 'les_98c70721c3dc932b', 'cvm-norm-hamming', 'mcq', 'The right distance for ORB', 'Which matcher is right for comparing **ORB** descriptors?', NULL, NULL, '', 'Each ORB descriptor is 256 bits packed into 32 numbers. `cv2.NORM_HAMMING` compares two descriptors by counting the bits that differ: 0 means identical, and small numbers mean "looks alike".', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
