INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_f72025702c51780a', '/courses/computer-vision/exercises/cvm-trace-hamming', 'Counting differing bits', 'a and b are one-number "descriptors", 193 and 195. The program compares them bit by bit, then asks OpenCV for their Hamming distance. What exactly does it print? import cv2 import numpy as np a = np.array([[193]], dtype=np.uint8) b = np.array([[195]], dtype=np.uint8) print(format(193, "08b"), format(195, "08b")) diff = np.unpackbits(a) != np.unpackbits(b) print(np.count_nonzero(diff)) print(cv2.norm(a, b, cv2.NORM_HAMMING))');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_cc43b365492fdb53', 'course_computer_vision', 'top_98c70721c3dc932b', 'les_98c70721c3dc932b', 'cvm-uniform-darkness', 'mcq', 'Why darkness barely matters', 'In the lecture''s experiment, making image B **uniformly darker** (half the brightness) kept 252 of 258 good matches, but **uneven lighting** kept only 91. Why?', NULL, NULL, '', 'Each bit of an ORB descriptor answers "is this pixel darker than that one?" Halving every pixel keeps every answer the same, so the descriptor hardly changes. When one side is darkened and the other brightened, some answers flip, the descriptors change, and fewer pairs match.', 'hard', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
