INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1e66853e44703106', 'course_computer_vision', 'exe_cc43b365492fdb53', 'ORB compares pixels with each other. Darkening everything equally keeps those comparisons the same; uneven lighting changes them.', 1, 'Right: if one pixel was darker than another, it still is after uniform darkening.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_8ff596b69560d6dd', 'course_computer_vision', 'exe_cc43b365492fdb53', 'ORB converts every image to the same brightness before it starts.', 0, 'ORB doesn''t adjust the brightness. The comparisons themselves are what make it robust.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b5f30e6e9b8d4c95', 'course_computer_vision', 'exe_cc43b365492fdb53', 'Darker images have more corners, so there are more matches.', 0, 'The number barely changed (252 of 258). Darkness didn''t add features.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_40fa0478b765ef9f', 'course_computer_vision', 'exe_cc43b365492fdb53', 'Uneven lighting makes the image smaller.', 0, 'Lighting doesn''t change the image''s size.', 4);
