INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_cc43b365492fdb53', '/courses/computer-vision/exercises/cvm-uniform-darkness', 'Why darkness barely matters', 'In the lecture''s experiment, making image B uniformly darker (half the brightness) kept 252 of 258 good matches, but uneven lighting kept only 91. Why?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_cff2491ce1269912', 'course_computer_vision', 'top_dee772f46241845b', 'les_e0c31345b781f8a8', 'cvn-average-smears', 'mcq', 'Why the average blur made it worse', 'In the lecture, the average error of the noisy street image was 5.1. After `cv2.blur(noisy, (5, 5))` it was **8.2**, worse than doing nothing. Why?', NULL, NULL, '', 'Each salt or pepper dot is an extreme value. An average filter adds it into every one of its neighbours'' new values, so one wrong pixel becomes a 5 × 5 patch of slightly wrong pixels. At the same time, real edges are softened. The median filter (error 2.8) picks an existing middle value instead, which ignores the dots.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
