INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d3cbae32d7781743', 'course_computer_vision', 'exe_cff2491ce1269912', 'The average spreads every dot into a smudge, and also blurs the real details.', 1, 'Right: the dots are not removed, only spread out, and the picture itself gets softer.', 1);
