INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_cff2491ce1269912', '/courses/computer-vision/exercises/cvn-average-smears', 'Why the average blur made it worse', 'In the lecture, the average error of the noisy street image was 5.1. After cv2.blur(noisy, (5, 5)) it was 8.2 , worse than doing nothing. Why?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_f2f0ad26d1395ea0', 'course_computer_vision', 'top_dee772f46241845b', 'les_e0c31345b781f8a8', 'cvn-choose-median', 'mcq', 'Black and white dots', 'A camera with a faulty sensor gives frames with **isolated pure black and pure white pixels** scattered over them. Which filter removes them best?', NULL, NULL, '', 'This is **salt-and-pepper noise**. The median filter sorts each neighbourhood and **picks** the middle value, so a lone 0 or 255 is never chosen. On the lecture''s noisy street image, a 5 × 5 median removed all 9,192 dots.

| Noise | Good choice |
|---|---|
| salt and pepper | `cv2.medianBlur` |
| fine grain on every pixel | `cv2.GaussianBlur` |', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
