INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a455aac236d76f2d', 'course_computer_vision', 'exe_f2f0ad26d1395ea0', '`cv2.GaussianBlur(img, (5, 5), 0)`', 0, 'A weighted average still adds the extreme values in. It works well for fine grain on every pixel, not for isolated dots.', 3);
