INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_f2f0ad26d1395ea0', '/courses/computer-vision/exercises/cvn-choose-median', 'Black and white dots', 'A camera with a faulty sensor gives frames with isolated pure black and pure white pixels scattered over them. Which filter removes them best?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_8073c7573a449338', 'course_computer_vision', 'top_dee772f46241845b', 'les_e0c31345b781f8a8', 'cvn-correct-median-index', 'correct_code', 'Fix the median of five neighbours', 'The program reads five neighbouring pixel values on one line and prints their median and their average. The median is often wrong. Fix it.', 'numbers = []
for text in input().split():
    numbers.append(int(text))
median = numbers[2]
average = round(sum(numbers) / len(numbers), 1)
print("median:", median)
print("average:", average)', 'python', 'The user types five whole numbers separated by spaces. The median is the middle value **after sorting**. For `12 14 255 13 0` the program prints:

```
median: 13
average: 58.8
```', 'Index 2 is the middle **position**, but the median is the middle **value**, and that is only at index 2 after sorting. In the first test, index 2 holds the white dot, 255. Sorted, the list is `[0, 12, 13, 14, 255]` and index 2 holds **13**.

The second test passes even with the bug, because its values were already in order. Sorting doesn''t change the average, since the sum stays the same.', 'medium', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
