INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_8073c7573a449338', '/courses/computer-vision/exercises/cvn-correct-median-index', 'Fix the median of five neighbours', 'The program reads five neighbouring pixel values on one line and prints their median and their average. The median is often wrong. Fix it. The user types five whole numbers separated by spaces. The median is the middle value after sorting . For 12 14 255 13 0 the program prints: median: 13 average: 58.8 numbers = [] for text in input().split(): numbers.append(int(text)) median = numbers[2] average = round(sum(numbers) / len(numbers), 1) print("median:", median) print("average:", average)');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_d3f5090464f12aa2', 'course_computer_vision', 'top_dee772f46241845b', 'les_e0c31345b781f8a8', 'cvn-odd-kernel', 'mcq', 'Which call runs?', '`img` is a loaded image. Which line runs **without an error**?', NULL, NULL, '', 'Every smoothing kernel needs a **centre pixel**, so its sizes must be odd: 3, 5, 7… The two functions take the size in different forms:

| Function | Size |
|---|---|
| `cv2.GaussianBlur(img, (k, k), 0)` | a tuple, (width, height) |
| `cv2.medianBlur(img, k)` | one number |', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
