INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_d3f5090464f12aa2', '/courses/computer-vision/exercises/cvn-odd-kernel', 'Which call runs?', 'img is a loaded image. Which line runs without an error ?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_a049d7b924df50bd', 'course_computer_vision', 'top_dee772f46241845b', 'les_e0c31345b781f8a8', 'cvn-trace-blur-rows', 'trace', 'Median and average on one row', '`row` is a tiny grayscale image, 1 pixel tall and 8 wide, with one white dot (255) and one black dot (0). Both filters look at each pixel and its left and right neighbours. What exactly does the program print?', 'import cv2
import numpy as np

row = np.array([[20, 20, 255, 20, 20, 0, 20, 20]], dtype=np.uint8)
print(cv2.medianBlur(row, 3))
print(cv2.blur(row, (3, 1)))', 'python', '', '**Median:** around the white dot the groups are (20, 20, 255), (20, 255, 20) and (255, 20, 20). Sorted, each one has **20** in the middle. The same happens around the black dot. Both dots are gone and nothing else changed.

**Average:** every group that contains the 255 averages to (20 + 20 + 255) ÷ 3 = 98.3, stored as **98**: one white dot became three light-grey pixels. Every group with the 0 averages to 40 ÷ 3 = 13.3, stored as **13**: one black dot became three dark-grey pixels. The average filter spreads the noise; the median removes it.', 'hard', 'auto', '{"compare":"normalize_whitespace","caseSensitive":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
