INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_fe07677ceb53d073', '/courses/computer-vision/exercises/cvn-trace-median-average', 'Median and average of a noisy patch', 'A 3 × 3 patch of a grey area near 90 has one white dot (255) and one black dot (0). What exactly does the program print? patch = [88, 92, 90, 255, 91, 89, 0, 93, 94] values = sorted(patch) print(values) print("median:", values[4]) print("average:", round(sum(patch) / len(patch), 1))');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_a62297c641b8cda2', 'course_computer_vision', 'top_dee772f46241845b', 'les_e0c31345b781f8a8', 'cvn-write-median-row', 'write_code', 'A median filter for one row', 'Write a program that reads a row of pixel values on one line, separated by spaces, and prints the row after a **median filter of size 3**: every pixel except the first and the last becomes the median of itself and its left and right neighbours. The first and last pixels stay as they are.

Print the new values on one line, separated by spaces. Use `input()` without a prompt.', '# read the row here
', 'python', 'For `20 20 255 20 20 0 20 20` the program prints `20 20 20 20 20 20 20 20`. For `10 50 12 13 200 14` it prints `10 12 13 13 14 14`.', 'This is what `cv2.medianBlur(img, 3)` does, along one row instead of a 3 × 3 square. Keeping the results in a separate List matters: a filter always computes every new pixel from the **original** neighbours. OpenCV handles the edge pixels by imagining extra pixels around the border; this exercise simply keeps them.', 'hard', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
