INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_ae3a0edd60366d57', 'course_computer_vision', 'exe_a62297c641b8cda2', 'reference_solution', 'row = []
for text in input().split():
    row.append(int(text))
new_row = [row[0]]
for i in range(1, len(row) - 1):
    three = sorted([row[i - 1], row[i], row[i + 1]])
    new_row.append(three[1])
new_row.append(row[-1])
print(" ".join(str(v) for v in new_row))', 1);
