INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_a62297c641b8cda2', '/courses/computer-vision/exercises/cvn-write-median-row', 'A median filter for one row', 'Write a program that reads a row of pixel values on one line, separated by spaces, and prints the row after a median filter of size 3 : every pixel except the first and the last becomes the median of itself and its left and right neighbours. The first and last pixels stay as they are. Print the new values on one line, separated by spaces. Use input() without a prompt. For 20 20 255 20 20 0 20 20 the program prints 20 20 20 20 20 20 20 20 . For 10 50 12 13 200 14 it prints 10 12 13 13 14 14 . # read the row here');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_868817d80ba7b3cc', 'course_computer_vision', 'top_b3d4cf2ba88a3e8e', 'les_68c8eb7ee571205f', 'cvp-correct-pixel-to-grey', 'correct_code', 'Fix the grey value calculator', 'The program reads one OpenCV pixel as three numbers on one line, in OpenCV''s order, and prints its grey value with **grey = 0.299 × R + 0.587 × G + 0.114 × B**, rounded. It gives wrong answers for coloured pixels. Fix it.', 'values = input().split()
r = int(values[0])
g = int(values[1])
b = int(values[2])
grey = 0.299 * r + 0.587 * g + 0.114 * b
print(round(grey))', 'python', 'The user types the pixel as B, G and R, separated by spaces, as OpenCV stores it. For the car pixel `60 60 200` the program prints `102`.', 'OpenCV stores **B, G, R**, so the first number typed is blue and the last is red. The program read them as R, G, B, which gives red''s weight to blue and blue''s weight to red. Pure green still passes, because green is in the middle either way; the other three tests fail.', 'medium', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
