INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_7c2792a29935ae0e', 'course_computer_vision', 'exe_57a5580fa47bb432', 'Pure blue, `(255, 0, 0)`', 1, 'Right: blue has the smallest weight, 0.114, so it becomes about 29.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_70efd5d352a5d244', 'course_computer_vision', 'exe_57a5580fa47bb432', 'Pure green, `(0, 255, 0)`', 0, 'Green has the biggest weight, 0.587, so it becomes about 150: the lightest of the three.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_19b13f772374a268', 'course_computer_vision', 'exe_57a5580fa47bb432', 'Pure red, `(0, 0, 255)`', 0, 'Red''s weight is 0.299, so it becomes about 76: darker than green, but lighter than blue.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_47c92c3cb56353ca', 'course_computer_vision', 'exe_57a5580fa47bb432', 'All three become the same grey, 85.', 0, 'That would be a plain average (255 ÷ 3). OpenCV gives each channel its own weight.', 4);
