INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_61cb018e3f3e094b', 'course_computer_vision', 'top_b3d4cf2ba88a3e8e', 'les_68c8eb7ee571205f', 'cvp-grayscale-flag', 'mcq', 'Load an image straight in grayscale', 'Which lines load `street.png` **directly as a grayscale image**? Pick **all** that do.', NULL, NULL, '', 'There are two ways to get a grayscale image:

1. Load it in grayscale: `cv2.imread(name, cv2.IMREAD_GRAYSCALE)`, or the same with `0`.
2. Load it in colour, then convert: `cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)`.

The two ways can round some pixels 1 grey level apart, so don''t mix them in one experiment.', 'medium', 'auto', '{"multiple":true,"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
