INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_08b6ff0b3e92a77a', 'course_computer_vision', 'exe_e85f3654aa4f65b5', '`102`, then `76`', 1, 'Right: `RGB2GRAY` reads the first number as red, so the car''s 200 gets blue''s small weight.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a8e6a40523eed1a3', 'course_computer_vision', 'exe_e85f3654aa4f65b5', '`102`, then `102`', 0, 'The code tells `cvtColor` which number is red. Swapping it changes which weight each number gets.', 2);
