INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_e85f3654aa4f65b5', '/courses/computer-vision/exercises/cvp-rgb2gray-mistake', 'BGR2GRAY or RGB2GRAY?', 'The car pixel from street.png is converted twice, once with each code. What does the program print? import cv2 import numpy as np car = np.array([[[60, 60, 200]]], dtype=np.uint8) # one pixel, B G R print(cv2.cvtColor(car, cv2.COLOR_BGR2GRAY)[0, 0]) print(cv2.cvtColor(car, cv2.COLOR_RGB2GRAY)[0, 0])');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_1afbae27b84c2b6b', 'course_computer_vision', 'top_b3d4cf2ba88a3e8e', 'les_68c8eb7ee571205f', 'cvp-trace-gray-shapes', 'trace', 'Shapes before and after cvtColor', '`np.zeros` makes a black colour image, 400 pixels wide and 300 tall, without reading a file. What exactly does the program print?', 'import cv2
import numpy as np

img = np.zeros((300, 400, 3), dtype=np.uint8)
gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
print(img.shape)
print(gray.shape)
print(len(gray.shape))', 'python', '', 'The height and width stay the same: the image is still 300 rows of 400 pixels. What changes is the last number. A colour pixel holds 3 numbers (B, G, R), so the shape ends with 3. A grey pixel holds just one, so the grayscale shape has **no channel dimension** at all: `(300, 400)`, two numbers.', 'easy', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
