INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_1afbae27b84c2b6b', '/courses/computer-vision/exercises/cvp-trace-gray-shapes', 'Shapes before and after cvtColor', 'np.zeros makes a black colour image, 400 pixels wide and 300 tall, without reading a file. What exactly does the program print? import cv2 import numpy as np img = np.zeros((300, 400, 3), dtype=np.uint8) gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY) print(img.shape) print(gray.shape) print(len(gray.shape))');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_c9fabbd2ebeaa872', 'course_computer_vision', 'top_b3d4cf2ba88a3e8e', 'les_68c8eb7ee571205f', 'cvp-unpack-gray-shape', 'mcq', 'Three names for a grey shape', '`gray` is a grayscale image with shape `(480, 640)`. What happens on this line?', 'h, w, c = gray.shape', 'python', '', 'Unpacking needs exactly as many names as there are values. For a grayscale image, write `h, w = gray.shape`. Only colour images have the third number: `h, w, c = img.shape`.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
