INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_d3988e679fa724f0', '/courses/computer-vision/exercises/cvp-value-grey-by-formula', 'A pixel''s grey value by hand', 'An OpenCV pixel holds [200, 100, 50] . The program works out its grey value with the formula from the lecture. What is the value of grey when the last line runs ? Type the number only. pixel = [200, 100, 50] b, g, r = pixel grey = round(0.299 * r + 0.587 * g + 0.114 * b) print("Converted")');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_f108f16f319edf28', 'course_computer_vision', 'top_002afa2197637fed', 'les_c5f7f82402451f6e', 'cvr-correct-shape-order', 'correct_code', 'Width and height from the shape', 'The program reads the three numbers of an image''s `img.shape` on one line, such as `540 960 3`, and prints the width, the height, and whether the image is wider than it is tall. It gets the width and height the wrong way round. Fix it.', 'numbers = input().split()
width = int(numbers[0])
height = int(numbers[1])
print("Width:", width)
print("Height:", height)
if width > height:
    print("Landscape")
else:
    print("Portrait")', 'python', 'The user types the shape as three numbers separated by spaces, in OpenCV''s order. For `540 960 3` the program prints:

```
Width: 960
Height: 540
Landscape
```', '`img.shape` is always **(height, width, channels)**: rows first, then columns. So `numbers[0]` is the height and `numbers[1]` is the width. With the bug, `street.png` would be reported as 540 wide, 960 tall and "Portrait", which is the opposite of the picture.', 'medium', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
