INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_f108f16f319edf28', '/courses/computer-vision/exercises/cvr-correct-shape-order', 'Width and height from the shape', 'The program reads the three numbers of an image''s img.shape on one line, such as 540 960 3 , and prints the width, the height, and whether the image is wider than it is tall. It gets the width and height the wrong way round. Fix it. The user types the shape as three numbers separated by spaces, in OpenCV''s order. For 540 960 3 the program prints: Width: 960 Height: 540 Landscape numbers = input().split() width = int(numbers[0]) height = int(numbers[1]) print("Width:", width) print("Height:", height) if width > height: print("Landscape") else: print("Portrait")');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_328978aafb1f33c8', 'course_computer_vision', 'top_002afa2197637fed', 'les_c5f7f82402451f6e', 'cvr-cv2-name-clash', 'mcq', 'A program file called cv2.py', 'OpenCV is installed. A student saves this program as **cv2.py** and runs it. It stops on line 3 with an `AttributeError` saying that `cv2` has no attribute `imread`. Why?', 'import cv2

img = cv2.imread("street.png")
print(img.shape)', 'python', '', 'When you write `import cv2`, Python first looks for a file named `cv2.py` in your program''s folder. If it finds one, it imports that instead of OpenCV. Rename your program, for example to `show_image.py`, and run it again.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
