INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_328978aafb1f33c8', '/courses/computer-vision/exercises/cvr-cv2-name-clash', 'A program file called cv2.py', 'OpenCV is installed. A student saves this program as cv2.py and runs it. It stops on line 3 with an AttributeError saying that cv2 has no attribute imread . Why? import cv2 img = cv2.imread("street.png") print(img.shape)');
