INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_e43efb4f18988ba1', 'course_computer_vision', 'top_002afa2197637fed', 'les_c5f7f82402451f6e', 'cvr-waitkey-zero', 'mcq', 'What waitKey(0) does', 'What does `cv2.waitKey(0)` do in this program?', 'import cv2

img = cv2.imread("street.png")
cv2.imshow("Original Image", img)
cv2.waitKey(0)
cv2.destroyAllWindows()', 'python', '', '`cv2.waitKey(0)` pauses the program until **any** key is pressed while the window is selected. Without it, the window would flash open and shut, or stay grey and frozen, because OpenCV only draws its windows while it waits for a key.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
