INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_computer_vision', 'exercise', 'exe_5d017a97369fa339', '/courses/computer-vision/exercises/cvz-correct-keep-ratio', 'Fix the aspect-ratio calculator', 'The program reads an image''s width and height, then the new width you want, and prints the new size that keeps the aspect ratio. The formula on one line is wrong. Fix it. The user types the old width, the old height and the new width, one per line. For 960 , 540 and 640 the program prints 640 x 360 . old_w = int(input()) old_h = int(input()) new_w = int(input()) new_h = int(old_w * new_w / old_h) print(new_w, "x", new_h)');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_89d6d02d32b9a5e3', 'course_computer_vision', 'top_2639c7e13ccd319a', 'les_776f7a5dd6219e8e', 'cvz-decimal-size-error', 'mcq', 'Resize stops with an error', '`img` is loaded correctly and is 540 pixels tall. Why does the last line stop with an error that says `Can''t parse ''dsize''`?', 'h = img.shape[0]
new_h = h * 0.5
small = cv2.resize(img, (480, new_h))', 'python', '', '`dsize` is the name of the size argument. OpenCV needs it as two **whole numbers**. Any calculation with `*` and a decimal, or with `/`, gives a float, so wrap calculated sizes in `int()`:

```python
new_h = int(h * 0.5)
```', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
