INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_9c4fd4b0f50514c6', 'course_computer_vision', 'top_2639c7e13ccd319a', 'les_776f7a5dd6219e8e', 'cvz-inter-area', 'mcq', 'Interpolation for shrinking', 'You are shrinking camera frames from 1920 × 1080 to 640 × 360. Which interpolation does OpenCV''s documentation recommend for **shrinking**?', NULL, NULL, '', '**Interpolation** is how `resize` calculates the new pixels. Pass it as an argument:

```python
small = cv2.resize(img, (640, 360), interpolation=cv2.INTER_AREA)
```

The default, `cv2.INTER_LINEAR`, is fine for most work. For enlarging, `INTER_CUBIC` (slower) or `INTER_LINEAR` are recommended.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
