INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_8c89fcaa994da41a', 'course_computer_vision', 'top_2639c7e13ccd319a', 'les_776f7a5dd6219e8e', 'cvz-trace-three-shapes', 'trace', 'Three resized shapes', '`img` is a black colour image the same size as `street.png`, 960 wide and 540 tall. What exactly does the program print?', 'import cv2
import numpy as np

img = np.zeros((540, 960, 3), dtype=np.uint8)
a = cv2.resize(img, (320, 180))
b = cv2.resize(img, (480, 640))
c = cv2.resize(img, None, fx=0.25, fy=0.5)
print(a.shape)
print(b.shape)
print(c.shape)', 'python', '', 'The size you give `cv2.resize` is **(width, height)**, but `shape` is **(height, width, channels)**, so the two numbers always appear swapped in the shape.

- `(320, 180)` keeps the 16:9 ratio, a quarter of the size each way.
- `(480, 640)` is the "giving (height, width)" mistake: it makes a **tall** image.
- `fx=0.25, fy=0.5` uses different factors, so the picture is squeezed sideways: 240 wide and 270 tall.', 'medium', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
