INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_72328a1b971eaa57', 'course_computer_vision', 'top_2639c7e13ccd319a', 'les_776f7a5dd6219e8e', 'cvz-why-shrink', 'mcq', 'Why shrink an image first?', 'Why do computer vision programs often shrink camera images before processing them? Pick **all** the right reasons.', NULL, NULL, '', 'Shrinking trades some detail for speed and memory. For many jobs, such as finding lane lines, a 640-pixel-wide frame still has all the detail the program needs.', 'easy', 'auto', '{"multiple":true,"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
