INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_5486b94d7d582bfd', 'course_computer_vision', 'top_2639c7e13ccd319a', 'les_776f7a5dd6219e8e', 'cvz-write-scale-percent', 'write_code', 'Scale by a percentage', 'Write a program that reads an image''s width, its height and a percentage (each on its own line), and prints the new size after scaling **both** sides by that percentage, as `width x height` with whole numbers.

Use `input()` without prompts.', '# read the width, the height and the percentage here
', 'python', 'For `960`, `540` and `50` the program prints `480 x 270`. For `640`, `480` and `150` it prints `960 x 720`.', 'Scaling both sides by the same percentage keeps the aspect ratio, just like `fx` and `fy` with the same value. In OpenCV, the result could be used straight away: `cv2.resize(img, (new_w, new_h))`, or `cv2.resize(img, None, fx=percent / 100, fy=percent / 100)`.', 'easy', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
