INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_9aab95480ea16bc7', 'course_computer_vision', 'exe_beb4947b5d946ad4', '`[[236  70 205]]`', 1, 'Right: 30 - 50 would be -20, which a `uint8` can''t hold. NumPy wraps around past 0 and stores 256 - 20 = 236.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cfdb8149cb2cd260', 'course_computer_vision', 'exe_beb4947b5d946ad4', '`[[  0  70 205]]`', 0, 'That''s what you **want** (stopping at 0), but NumPy''s `-` on `uint8` doesn''t stop at the limit. It wraps around.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_00b64e90cfc7dbec', 'course_computer_vision', 'exe_beb4947b5d946ad4', '`[[-20  70 205]]`', 0, 'A `uint8` is unsigned: it can only hold whole numbers from 0 to 255, never a negative number.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_821af865bec112de', 'course_computer_vision', 'exe_beb4947b5d946ad4', 'It stops with an overflow error.', 0, 'NumPy doesn''t raise an error here. It quietly wraps the value around, which is why this bug is easy to miss.', 4);
