INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_b982fe91dcca39c6', 'course_computer_vision', 'exe_93c5084c2a8ae04c', 'reference_solution', 'img = [[12, 40, 80, 120],
