INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_4accb2d95bf553a1', 'course_computer_vision', 'exe_6a6ee0ce6d2ebde0', 'reference_solution', 'value = int(input())
beta = int(input())
total = value + beta
wrapped = total % 256
saturated = min(total, 255)
