INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_dddf834e51172f76', 'course_programming_applications', 'top_f56e7e4421d112fa', 'les_bed6deb54f895c3d', 'correct-first-and-last-character', 'correct_code', 'Fix the first and last character', 'This program should read a word and print its first character followed by its last character. It has **two** bugs. Find them and fix the program.', 'word = input()
