INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'exercise', 'exe_899c16aa928e1b1d', '/courses/programming-applications/exercises/count-py-cart-loop-rounds', 'How many rounds does the cart loop make?', 'A shopping cart holds prices. The List is changed a few times before the total is worked out. How many times does the body of the for loop run? Type a number. cart = [25, 40, 15] cart.append(10) cart.insert(1, 30) cart.remove(40) cart.pop() total = 0 for price in cart: total = total + price print("Total:", total)');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_3c7f1ed7261fe1b0', 'course_programming_applications', 'top_7a6ac98b95c0c58e', 'les_169dba8964c25c2b', 'gfx-bottom-left-point', 'mcq', 'Nearest the bottom-left corner', 'A window is made with `GraphWin("Map", 400, 300)`. Which point is **nearest the bottom-left corner**?', NULL, NULL, '', '(0, 0) is the **top-left** corner. x counts pixels from the left edge, and y counts pixels **down** from the top edge. In a 400 × 300 window the bottom-left corner is (0, 300), and (20, 280) is only 20 pixels from each of those two edges.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
