INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_f2e1fef8afc055fa', 'course_programming_applications', 'top_7a6ac98b95c0c58e', 'les_b638a80716b65acd', 'gfx-draw-order', 'mcq', 'Where did the red light go?', 'This program should show a red light on a black traffic-light body. What does the window show?', 'from graphics import *

win = GraphWin("Light", 300, 500)
light = Circle(Point(150, 140), 50)
light.setFill("red")
light.draw(win)
body = Rectangle(Point(75, 50), Point(225, 450))
body.setFill("black")
body.draw(win)
win.getMouse()
win.close()', 'python', '', 'Each `draw()` paints the shape **on top of** everything already in the window. Here the red circle is painted first and the black rectangle, which surrounds it completely, is painted over it. The fix is to draw back to front: create and draw the body first, then the light.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
