INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'exercise', 'exe_f2e1fef8afc055fa', '/courses/programming-applications/exercises/gfx-draw-order', 'Where did the red light go?', 'This program should show a red light on a black traffic-light body. What does the window show? from graphics import * win = GraphWin("Light", 300, 500) light = Circle(Point(150, 140), 50) light.setFill("red") light.draw(win) body = Rectangle(Point(75, 50), Point(225, 450)) body.setFill("black") body.draw(win) win.getMouse() win.close()');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_a67507b8ea31998c', 'course_programming_applications', 'top_7a6ac98b95c0c58e', 'les_bddd50d355ecf96e', 'gfx-getmouse-returns', 'mcq', 'What does getMouse() give back?', 'What does `click` refer to after this line runs and the user clicks inside the window?', 'click = win.getMouse()', 'python', '', '`win.getMouse()` waits for a click, then **returns a Point object** at the click position. That is why `Circle(click, 30)` works: a Circle needs a center Point, and `click` is one.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
