INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'exercise', 'exe_b35ed0d9dd755cb9', '/courses/programming-applications/exercises/gfx-value-click-message', 'Build a message from a click', 'In this program a Point stands in for a click at (45, 380). What is the value of msg when the last line runs ? Type the text exactly, without quotes. from graphics import * click = Point(45, 380) x = int(click.getX()) y = click.getY() msg = "Clicked at " + str(x) + ", " + str(y) print("Message ready")');
