INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_119067dd7c1f6c52', 'course_programming_applications', 'top_57b5d29d21e9f710', 'les_827e9b6d6383ec94', 'intro-trace-comments-and-commas', 'trace', 'Comments and commas', 'What exactly does this program print? Type one line of output per line.', '# Lecture 1 notes
print("Python", "is", "simple")
# print("C++ needs more lines")
print("Lines:", 1)
print("Done")', 'python', '', 'Lines 1 and 3 start with `#`, so they are **comments** and never run. Line 3 looks like a `print`, but the `#` in front turns the whole line into a note for people.

`print` with commas prints every item on one line with a single space between them, so `print("Python", "is", "simple")` gives `Python is simple`, and `print("Lines:", 1)` gives `Lines: 1`. Each `print` then starts a new line.', 'easy', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
