INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'exercise', 'exe_119067dd7c1f6c52', '/courses/programming-applications/exercises/intro-trace-comments-and-commas', 'Comments and commas', 'What exactly does this program print? Type one line of output per line. # Lecture 1 notes print("Python", "is", "simple") # print("C++ needs more lines") print("Lines:", 1) print("Done")');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_95c9f7ce0c6cb1e1', 'course_programming_applications', 'top_57b5d29d21e9f710', 'les_827e9b6d6383ec94', 'intro-which-print-works', 'mcq', 'Which line prints the greeting?', 'Which line prints exactly `Hello, World!` on the screen?', NULL, NULL, '', 'A working `print` line needs all three parts: the function name `print` in small letters, a pair of brackets, and the text in straight quotes. Each wrong option breaks one of them:

- a capital letter in the name gives a `NameError` when Python reaches that line;
- missing quotes or a missing bracket are grammar mistakes (`SyntaxError`), found before any line runs.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1792022400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
