INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_65a3b449a2271a57', 'course_programming_applications', 'exe_95c9f7ce0c6cb1e1', '`Print("Hello, World!")`', 0, 'Python is case-sensitive. `Print` with a capital P is not a function Python knows, so it stops with `NameError: name ''Print'' is not defined`.', 2);
