INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_68f4d75f59f47114', 'course_programming_applications', 'top_dbb55f4ba4d26c33', 'les_02f87c25ff83b0e2', 'io-blanks-rectangle-area', 'correct_code', 'The area of a rectangle', 'The program reads the width and the height of a rectangle in metres and prints its area. The sizes can have a decimal point, such as `2.5`. Fill in the **two blanks**.', 'width = ___(input())
height = ___(input())
area = width * height
print("Area:", area)', 'python', 'The user types the width, then the height. For `2.5` and `4` the program prints `Area: 10.0`.', 'Both blanks are `float`. `input()` gives text, and `float()` turns it into a decimal number. `int()` would stop with a `ValueError` for `2.5`, because it only accepts whole numbers.

Because the sizes are floats, the area is a float too: 2.5 × 4.0 is printed as `10.0`.', 'easy', 'reference_review', '{"ask":"blanks","compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
