INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_f8809410e427665a', 'course_programming_applications', 'top_dbb55f4ba4d26c33', 'les_02f87c25ff83b0e2', 'io-order-average-of-two', 'correct_code', 'Put the average program in order', 'The program reads two marks and prints their average. Move the mixed-up lines into the right order: input, then processing, then output.', '# [order]
a = float(input())
b = float(input())
average = (a + b) / 2
print("Average:", average)
# [/order]', 'python', 'The user types two marks. For `70` and `85` the program prints `Average: 77.5`.', 'The order follows **input → processing → output**:

1. Read the two marks (input). These two lines can swap: the average is the same whichever mark goes into `a`.
2. `average = (a + b) / 2` needs both marks, so it comes after them (processing).
3. `print` shows the result, so it comes last (output).

The brackets make Python add the marks before dividing; `/` always gives a float, so 90 and 90 give `90.0`.', 'easy', 'reference_review', '{"ask":"order","compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
