INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_2a507af9923cbcfd', 'course_programming_applications', 'top_e57cde355af1cd13', 'les_acf2557a43d5a105', 'obj-correct-dot-calls', 'correct_code', 'Fix the two method calls', 'The program reads a friend''s name, adds it to the List and prints the name in capitals, then the whole List. Two method calls are written wrongly. Fix them.', 'friends = ["Ali", "Sara"]
name = input()
friends.append name
print(name.upper)
print(friends)', 'python', 'The user types a name. The program prints the name in capital letters, then the List with the new name added at the end.', 'A method call always has the pattern `object.method(argument)`:

1. `friends.append name` is missing the brackets, which is a `SyntaxError`. The argument goes **inside** them: `friends.append(name)`.
2. `name.upper` names the method but doesn''t call it, so `print` would show something like `<built-in method upper of str object at …>` instead of the capitals. `upper()` needs no argument, but the brackets are still required: `name.upper()`.', 'easy', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
