INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_applications', 'exercise', 'exe_ff46bd405b73b134', '/courses/programming-applications/exercises/ops-value-seconds-left', 'Hours, minutes and seconds', 'The program splits 3725 seconds into hours, minutes and seconds. What is the value of seconds when the last line runs ? Type the number only. total = 3725 hours = total // 3600 rest = total % 3600 minutes = rest // 60 seconds = rest % 60 print(hours, "h", minutes, "min")');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_6042099a9ba0006c', 'course_programming_applications', 'top_dba1aa73426c9dc9', 'les_e4a148e8ad10dfbd', 'ops-write-weeks-and-days', 'write_code', 'Weeks and days', 'Write a program that reads a whole number of days and prints how many whole weeks and extra days that is, in this form:

```
100 days is 14 weeks and 2 days
```

Use `//` and `%`.', 'days = int(input())
# work out the weeks and the days left over
', 'python', 'The user types a whole number of days. The program prints one line: the number, `days is`, the whole weeks, `weeks and`, the days left over and `days`.', '`days // 7` counts the **whole** weeks and drops the rest: 100 // 7 is 14. `days % 7` is the **remainder**: 100 − 14 × 7 = 2. This is the same pattern as turning minutes into hours and minutes, with 7 instead of 60.

(The output says "1 weeks" to keep the program short; making it say "1 week" needs an `if`, which you can add as an extra.)', 'medium', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1792108800000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
