INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d264f1f78a5a0fb3', 'course_programming_applications', 'exe_e2f5cedf402ab923', '`xorLux`', 0, 'The stop index is **not** included: `word[:2]` takes indexes 0 and 1 only, so it is `Lu`, not `Lux`.', 2);
