INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_2e1a21e8a12a137d', 'course_programming_fundamentals', 'top_e6268b080b4bf2c7', 'les_ae371952c0c968ae', 'algo-at-least-condition', 'mcq', 'Writing "at least" in C++', 'A student passes when the mark is **at least 50**. How do you write this condition the way C++ needs it?', NULL, NULL, '', '"At least 50" means 50 or more, so 50 itself must be included. That is "greater than or equal to", which C++ (and our pseudocode) writes as `>=`.

The maths symbol `≥` is not on your keyboard and is not C++. The other C++ forms are `<=` for "less than or equal to", `==` for "is equal to" and `!=` for "is not equal to".', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
