INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_5ce4a92082c452ab', 'course_programming_fundamentals', 'exe_2e1a21e8a12a137d', '`mark > 50`', 0, '`>` means "greater than", so a mark of exactly 50 would not pass. "At least" includes 50.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_0128ea2ffec3cb37', 'course_programming_fundamentals', 'exe_2e1a21e8a12a137d', '`mark >= 50`', 1, 'Right: `>=` means "greater than or equal to", so 50 and every mark above it pass.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_60927251ac4e854d', 'course_programming_fundamentals', 'exe_2e1a21e8a12a137d', '`mark ≥ 50`', 0, 'This is the maths symbol. Your keyboard has no `≥` key, and C++ does not understand it. Write `>=`.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_7789c6813a7b22af', 'course_programming_fundamentals', 'exe_2e1a21e8a12a137d', '`mark => 50`', 0, 'The order of the two symbols is wrong. C++ writes "greater than or equal to" as `>=`.', 4);
