INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_126da57e9d14cc2b', 'course_programming_fundamentals', 'top_e6268b080b4bf2c7', 'les_ae371952c0c968ae', 'algo-decision-shape', 'mcq', 'The shape for a question', 'In a flowchart, which shape do you use for the step "Is the price more than 100?"', NULL, NULL, '', 'Each flowchart shape has one meaning: **oval** = start/end, **parallelogram** = input/output, **rectangle** = process, **diamond** = decision, **arrow** = the order of the steps.

"Is the price more than 100?" is a question with a yes/no answer, so it is a **decision**. It goes in a diamond, which has two exits: one path for YES and one for NO. Only one of the two paths is followed each time.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
