INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c2bf36261cc5708c', 'course_programming_fundamentals', 'exe_03bb1dccf6d77c7d', 'B, C, D, A', 0, 'Step C divides SUM, but SUM has no value yet. The sum must be worked out first.', 2);
