INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_03bb1dccf6d77c7d', '/courses/programming-fundamentals/exercises/algo-order-the-steps', 'Putting the average steps in order', 'These four steps of the "average of three numbers" algorithm are mixed up: - A. Print AVERAGE. - B. Read the three numbers N1, N2 and N3. - C. Divide SUM by 3 and store the result in AVERAGE. - D. Add the three numbers and store the result in SUM. Between Start and End, which order is correct?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_ef517fd914518e59', 'course_programming_fundamentals', 'top_e6268b080b4bf2c7', 'les_ae371952c0c968ae', 'algo-parallelogram-steps', 'mcq', 'Which steps are parallelograms?', 'You are drawing a flowchart. Which of these steps go in a **parallelogram**? Choose all that apply.', NULL, NULL, '', 'The parallelogram is used for both **input** and **output**: reading a value (like "Read the mark" or `Input T`) and printing a value (like `Print AVERAGE`).

A calculation such as `total ← a + b` is **processing**, so it goes in a rectangle. A question such as "Is x > 0?" is a **decision**, so it goes in a diamond with YES and NO exits.', 'medium', 'auto', '{"multiple":true,"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
