INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_6894937126e12499', '/courses/programming-fundamentals/exercises/algo-trace-average', 'Tracing the average of three numbers', 'Trace this pseudocode by hand. What exactly does it print? Type one value per line. BEGIN N1 ← 7 N2 ← 9 N3 ← 14 SUM ← N1 + N2 + N3 PRINT SUM AVERAGE ← SUM / 3 PRINT AVERAGE END');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_aea02fc8d156b226', 'course_programming_fundamentals', 'top_e6268b080b4bf2c7', 'les_ae371952c0c968ae', 'algo-trace-fan-at-30', 'trace', 'The fan when T is exactly 30', 'The sensor reads exactly 30 °C. Trace this pseudocode by hand. What exactly does it print? Type one line of output per line.', 'BEGIN
    T ← 30
    IF T > 30 THEN
        PRINT "Fan ON"
    ELSE
        PRINT "Fan OFF"
    END IF
    PRINT "Done"
END', 'pseudocode', '', '`>` means "greater than", and 30 is **not** greater than 30, so the condition `T > 30` is FALSE. The ELSE path runs and prints `Fan OFF`. The THEN path is skipped completely: a decision creates two paths, and only one of them runs.

After `END IF`, both paths meet again, so `PRINT "Done"` runs every time, whatever the temperature. The fan would only turn on for a temperature above 30, such as 31.', 'medium', 'auto', '{"compare":"trim_trailing","caseSensitive":true,"verify":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\nint main()\n{\n    float t = 30;\n    if (t > 30)\n        cout << \"Fan ON\" << endl;\n    else\n        cout << \"Fan OFF\" << endl;\n    cout << \"Done\" << endl;\n    return 0;\n}"}}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
