INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_aea02fc8d156b226', '/courses/programming-fundamentals/exercises/algo-trace-fan-at-30', 'The fan when T is exactly 30', 'The sensor reads exactly 30 °C. Trace this pseudocode by hand. What exactly does it print? Type one line of output per line. BEGIN T ← 30 IF T > 30 THEN PRINT "Fan ON" ELSE PRINT "Fan OFF" END IF PRINT "Done" END');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_b83bee1e3a7928ce', 'course_programming_fundamentals', 'top_e519989412df8f8b', 'les_1946d5476bda30c9', 'blanks-book-pages-per-day', 'correct_code', 'Fill in the blanks to count reading days', 'Salma reads 25 pages of a book every day. The program reads the number of pages in the book and prints how many days she needs to finish it. Fill in the **three blanks**: the first is a comparison operator, the other two are short calculations.', '#include <iostream>
using namespace std;
int main()
{
    int pages;
    cin >> pages;
    int pagesRead = 0;
    int days = 0;
    while (pagesRead ___ pages)
    {
        pagesRead = ___;
        days = ___;
    }
    cout << "Days: " << days << endl;
    return 0;
}', 'cpp', 'The user types the number of pages. Each day Salma reads 25 more pages. The program prints `Days: ` followed by the number of days until she has read the whole book. On the last day she may read fewer than 25 pages, but it still counts as a day.', '1. `pagesRead < pages`: keep reading while some pages are still unread. With `<=`, a 100-page book would take 5 days, because the loop would run once more when `pagesRead` is exactly 100.
2. `pagesRead + 25` (or `25 + pagesRead`): 25 more pages each day.
3. `days + 1` (or `1 + days`): one more day each pass.

Trace for 110 pages:

| Day | pagesRead before | Check | pagesRead after |
|---|---|---|---|
| 1 | 0 | 0 < 110 TRUE | 25 |
| 2 | 25 | 25 < 110 TRUE | 50 |
| 3 | 50 | 50 < 110 TRUE | 75 |
| 4 | 75 | 75 < 110 TRUE | 100 |
| 5 | 100 | 100 < 110 TRUE | 125 |
| | 125 | 125 < 110 FALSE | |

The loop ran 5 times, so `Days: 5`. On day 5 she only needed 10 pages, but it is still a day.', 'medium', 'reference_review', '{"ask":"blanks","compare":"trim_trailing"}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
