INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_b0755625c416d62a', 'course_programming_fundamentals', 'top_d06bd9ff15d1e6cd', 'les_810ecce8c9e38678', 'blanks-speed-camera-fine', 'correct_code', 'Fill in the blanks for the speed camera', 'On this road the speed limit is 80 km/h. Driving at exactly 80 is allowed. Above 80, the driver pays 10 pounds for every km/h over the limit. Fill in the **two blanks**: the first is a comparison operator, the second is a short calculation.', '#include <iostream>
using namespace std;
int main()
{
    int speed, fine;
    cin >> speed;
    if (speed ___ 80)
    {
        fine = (___) * 10;
        cout << "Fine: " << fine << " pounds" << endl;
    }
    else
    {
        cout << "No fine" << endl;
    }
    return 0;
}', 'cpp', 'The user types a speed. If it is more than 80, the program prints `Fine: ` followed by 10 × (the km/h over 80) and ` pounds`. Otherwise it prints `No fine`.', '1. `speed > 80`: only speeds **above** 80 get a fine. With `>=`, a driver at exactly 80 would see `Fine: 0 pounds` instead of `No fine`. That''s why the boundary value 80 is one of the tests.
2. `speed - 80`: the number of km/h over the limit. At 95 km/h that is 15, and 15 × 10 = 150 pounds.

The brackets around `speed - 80` matter: they make the subtraction happen before the multiplication.', 'easy', 'reference_review', '{"ask":"blanks","compare":"trim_trailing"}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
