INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_34923c75c0c0e2c5', 'course_programming_fundamentals', 'top_e519989412df8f8b', 'les_e81daa799465081b', 'correct-sum-1-to-n', 'correct_code', 'Fix the sum from 1 to n', 'This program should read a whole number `n` and print the sum 1 + 2 + … + n. It has **two** bugs. Find them and fix the program.', '#include <iostream>
using namespace std;
int main()
{
    int n;
    cin >> n;
    int sum;
    int i = 1;
    while (i < n)
    {
        sum += i;
        i++;
    }
    cout << "Sum = " << sum << endl;
    return 0;
}', 'cpp', 'The user types a whole number `n` (1 or more). The program prints `Sum = ` followed by 1 + 2 + … + n. For 5 it prints `Sum = 15`.', '1. **`int sum;` has no starting value.** A local variable holds whatever was in memory, so `sum += i` adds to garbage. An accumulator must start at 0: `int sum = 0;`.
2. **`i < n` stops one step early.** For n = 5 the loop adds 1, 2, 3, 4 and stops when `i` is 5, so 5 is never added. Use `i <= n` (or `i < n + 1`).', 'medium', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
