INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_ea6ae33cc5d86f09', 'course_programming_fundamentals', 'exe_360c1372c98024f0', 'reference_solution', '#include <iostream>
