INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_f0509aa280f5eb30', 'course_programming_fundamentals', 'exe_2eef89f25b4840a9', '`do { cin >> number; } while (number <= 0);`', 1, 'Right: `do` opens the loop, the body comes first, and `while (condition);` ends it with a semicolon.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d39fa2060e3f3e60', 'course_programming_fundamentals', 'exe_2eef89f25b4840a9', '`do { cin >> number; } while (number <= 0)`', 0, 'The semicolon after `while (number <= 0)` is missing. In a do-while it is required, and g++ stops with an error without it.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1b23532c93059b26', 'course_programming_fundamentals', 'exe_2eef89f25b4840a9', '`do (number <= 0) { cin >> number; }`', 0, 'The condition doesn''t go after `do`. In a do-while it comes at the end, after the body.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_85f095c1b76d9ca9', 'course_programming_fundamentals', 'exe_2eef89f25b4840a9', '`while (number <= 0); { cin >> number; }`', 0, 'This is a normal `while` with a bug: the `;` becomes the whole loop body. It also checks `number` before any value has been read.', 4);
