INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_f18c5e7cd596d72c', 'course_programming_fundamentals', 'exe_febcbee509cf49c1', 'Print the 6 marks of a student, one per line.', 0, 'The count, 6, is known before the loop starts. Count known → `for`.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_815ab4644d47e87b', 'course_programming_fundamentals', 'exe_febcbee509cf49c1', 'Print the numbers from 1 to `n`, where `n` is typed by the user and may be 0 (then nothing should be printed).', 0, 'A do-while body always runs at least once, so it would print something even when `n` is 0. This task needs a loop that can run 0 times.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c04af60478744029', 'course_programming_fundamentals', 'exe_febcbee509cf49c1', 'Ask the user for their age, and ask again while the age is less than 1.', 1, 'Right: the question must be asked at least once before the program can check the answer. Must run once → `do-while`.', 3);
