INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_dcc912d042c0617b', 'course_programming_fundamentals', 'exe_63616028b86edb85', '`INPUT hours`, then `IF hours <= 2 THEN PRINT "Free" ELSE PRINT "Pay" END IF`', 1, 'Same: it asks the opposite question and swaps the two paths. `hours <= 2` is TRUE exactly when `hours > 2` is FALSE.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4c1540bbd27ed20a', 'course_programming_fundamentals', 'exe_63616028b86edb85', '`INPUT hours`, then `IF hours >= 3 THEN PRINT "Pay" ELSE PRINT "Free" END IF`', 1, 'Same: for whole numbers, "more than 2" means 3 or more. Both conditions are TRUE for 3, 4, 5… and FALSE for 2, 1, 0.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a7fb242009cf33ab', 'course_programming_fundamentals', 'exe_63616028b86edb85', '`INPUT hours`, then `IF hours < 2 THEN PRINT "Free" ELSE PRINT "Pay" END IF`', 0, 'Different at the edge: for exactly 2 hours, `2 < 2` is FALSE, so it prints `Pay`. The flowchart prints `Free` for 2 hours.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_17e319ad4a24b3e5', 'course_programming_fundamentals', 'exe_63616028b86edb85', '`INPUT hours`, then `IF hours > 2 THEN PRINT "Free" ELSE PRINT "Pay" END IF`', 0, 'The question is right, but the paths are swapped: the TRUE path (THEN) must be the diamond''s YES exit, which prints `Pay`.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_dcc912d042c0617b', 'course_programming_fundamentals', 'exe_63616028b86edb85', 'The diamond''s YES exit becomes the `THEN` part; the NO exit becomes the `ELSE` part.', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_4c1540bbd27ed20a', 'course_programming_fundamentals', 'exe_63616028b86edb85', 'Test every option with the edge values: 2 hours and 3 hours. What does the flowchart print for each?', 2);
