INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_e988a298b7c094bb', 'course_programming_fundamentals', 'exe_a364cf3ccabe13f5', 'Compiling with no errors does not prove that the program is correct.', 1, 'True: the compiler only stops when the code itself is wrong. It translated this code without complaint, but the steps it was given are the wrong steps.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_35ddb23b4f248fef', 'course_programming_fundamentals', 'exe_a364cf3ccabe13f5', 'The mistake is in the processing step, line 7.', 1, 'True: the input (line 6) and the output (line 8) work. Line 7 adds the two numbers when it should multiply them: `price * quantity`.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_5c276cda431c3f6b', 'course_programming_fundamentals', 'exe_a364cf3ccabe13f5', 'The CPU ran the text in `main.cpp` directly, so the compiler never saw the mistake.', 0, 'False: the CPU can''t read C++. The compiler translated `main.cpp` into machine code first, and the CPU ran that machine code.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_eee478cb6c0bd3ec', 'course_programming_fundamentals', 'exe_a364cf3ccabe13f5', 'The mistake is in the input: `cin` should read `quantity` before `price`.', 0, 'False: the order doesn''t matter for the answer here. Even with the two values swapped, `3 + 20` is still 23. The problem is the `+`.', 4);
