INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b800388f5a0ab9fe', 'course_programming_fundamentals', 'exe_21433b8e9bd85bac', '`cout << "Total = "; cout << 3 * 4 << "\n";`', 1, 'Correct: the first `cout` has no line break, so the second continues on the same line. `"\n"` then ends the line, just like `endl`.', 2);
