INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_860e3029b8f3c099', 'course_programming_fundamentals', 'exe_35b571c6c838d427', 'reference_solution', '#include <iostream>
using namespace std;
int main()
{
    int n;
    cin >> n;
    int sum = 0;
    int count = 0;
    for (int i = 5; i <= n; i += 5)
    {
        sum += i;
        count++;
    }
    cout << "Count: " << count << endl;
    cout << "Sum: " << sum << endl;
    return 0;
}', 1);
