INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a3e92f957f9393e9', 'course_programming_fundamentals', 'exe_8681213a7ac55e55', '`int i = 1; while (i <= 5) cout << i; i++;`', 1, 'Right: without braces, only `cout << i;` is inside the loop. `i++` would only run after the loop, so `i` stays 1 forever.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_ade551f8d01c2614', 'course_programming_fundamentals', 'exe_8681213a7ac55e55', '`int x = 10; while (x > 0) { cout << x; x -= 3; }`', 0, 'This one stops. `x` goes 10, 7, 4, 1, -2. It never equals 0, but the condition is `x > 0`, and `-2 > 0` is FALSE.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b5c6201101db7452', 'course_programming_fundamentals', 'exe_8681213a7ac55e55', '`int i = 1; do { cout << i; i += 2; } while (i != 6);`', 1, 'Right: `i` goes 1, 3, 5, 7, 9 … It jumps over 6, so `i != 6` stays TRUE forever.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_72927090bdc59949', 'course_programming_fundamentals', 'exe_8681213a7ac55e55', '`int i = 0; while (i <= 5) { cout << i; i = i * 2; }`', 1, 'Right: there is an update, but 0 × 2 is still 0. `i` never changes, so `0 <= 5` is always TRUE.', 4);
