INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c53d588823628e8e', 'course_programming_fundamentals', 'exe_ea3842cc8c4e472e', '`Print "Hi"` runs 4 times.', 1, 'Right: `count` is 0, 1, 2 and 3 when the answer is YES. At 4 the answer is NO.', 1);
