INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d38c139c50bc0c3d', 'course_programming_fundamentals', 'exe_ea3842cc8c4e472e', 'The rectangle `count ← 0` runs again every time the arrow goes back up.', 0, 'The backward arrow goes to the diamond, not to the start. The initialization runs only once.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_89593900b6929b8a', 'course_programming_fundamentals', 'exe_ea3842cc8c4e472e', 'Without the rectangle `count ← count + 1`, the flowchart would never reach End.', 1, 'Right: `count` would stay 0, so `0 < 4` would always be YES. That is an infinite loop.', 4);
