INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_975d659e8697c1ff', 'course_programming_fundamentals', 'exe_3b65c12f62955b55', '`2`', 1, 'Right: 6 multiples of 3 add 1 each, and 4 multiples of 5 take 1 away each: 6 − 4 = 2.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_137671981dd61be4', 'course_programming_fundamentals', 'exe_3b65c12f62955b55', '`3`', 0, 'This would be the answer if the second check were an `else`, so that 15 was only counted once. Here both `if`s run for 15: +1, then −1.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_f81d946d3ef2bc96', 'course_programming_fundamentals', 'exe_3b65c12f62955b55', '`6`', 0, 'That is only the multiples of 3. The second `if` also runs in every pass and takes 1 away for each multiple of 5.', 3);
