INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_07a218c5684160b8', 'course_programming_fundamentals', 'exe_00b40d7e75d6566a', '`for (int i = 10; i >= 0; i -= 2) { cout << "*"; }`', 0, '`i` is 10, 8, 6, 4, 2 **and 0**: `0 >= 0` is TRUE. That is 6 stars, one too many.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_92f1a86bb677b820', 'course_programming_fundamentals', 'exe_00b40d7e75d6566a', '`int i = 0; do { cout << "*"; i += 5; } while (i < 20);`', 0, 'The body runs with `i` = 0, 5, 10 and 15. After that `i` is 20, and `20 < 20` is FALSE. That is only 4 stars.', 4);
