INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_23eaf94bb82b3fea', 'course_programming_fundamentals', 'exe_3679df6f0113d98b', '`5 5 5 0`', 1, 'Right: three calls of 5 minutes are counted and added, 5 + 5 + 5 = 15. Then the 0 ends the loop; it is not counted.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1be054b2679bfc1f', 'course_programming_fundamentals', 'exe_3679df6f0113d98b', '`10 2 3 0 9`', 1, 'Right: 10, 2 and 3 are three calls, 15 minutes in all. The loop stops at the 0, so the 9 after it is never read.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_913ce3d437680396', 'course_programming_fundamentals', 'exe_3679df6f0113d98b', '`7 8 0 0`', 0, 'The total is right, 7 + 8 = 15, but the loop stops at the **first** 0. Only 2 calls are counted: it prints `Calls: 2 Total: 15`.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_97780aee9e91612b', 'course_programming_fundamentals', 'exe_3679df6f0113d98b', '`4 0 6 5`', 0, 'The loop stops at the 0 right after the 4, so 6 and 5 are never read. It prints `Calls: 1 Total: 4`.', 4);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_7493ad40c108c5a3', 'course_programming_fundamentals', 'exe_3679df6f0113d98b', '`0 5 5 5 0`', 0, 'The first value is already 0, so `0 != 0` is FALSE before the first pass. The body never runs: it prints `Calls: 0 Total: 0`.', 5);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_23eaf94bb82b3fea', 'course_programming_fundamentals', 'exe_3679df6f0113d98b', 'The first `cin` is before the loop. The loop checks each value **before** counting it.', 1);
