INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_86570725cc3ea2f4', 'course_programming_fundamentals', 'exe_d52a59ee9cc95e7a', 'The row for `i = 3`: `total` should be 4, not 6.', 1, 'Right: `total += i * 2` **adds** 6 to the old total, −2, so the result is 4. The student stored 6 as if the line were `total = i * 2`. The rows after it are worked out correctly, but from a wrong value.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_7df08ba32243c5ac', 'course_programming_fundamentals', 'exe_d52a59ee9cc95e7a', 'The row for `i = 1`: `total` should be 0, because `total` starts at 0.', 0, '`1 % 3` is 1, not 0, so the `else` path runs in the first pass and takes 1 away: 0 − 1 = −1. That row is right.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_5b979dc0ad610d55', 'course_programming_fundamentals', 'exe_d52a59ee9cc95e7a', 'The row for `i = 4`: `total` should stay the same, because 4 is not a multiple of 3.', 0, 'When `4 % 3 == 0` is FALSE, the `else` path runs, and it **does** change `total`: it takes 1 away. Taking 1 from the value above is the right step.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_03fa368f28288784', 'course_programming_fundamentals', 'exe_d52a59ee9cc95e7a', 'The row for `i = 6`: `total` should be 18.', 0, 'The student''s step here is right: 4 + 6 × 2 = 16 adds 12 to the row above. The difference comes from an earlier row, so this is not the **first** mistake.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_86570725cc3ea2f4', 'course_programming_fundamentals', 'exe_d52a59ee9cc95e7a', 'Check each row from the top, using the row above it as the old value. Which path runs for each `i`?', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_7df08ba32243c5ac', 'course_programming_fundamentals', 'exe_d52a59ee9cc95e7a', '`total += x` means `total = total + x`. Does the student''s row for `i = 3` add anything to the old total?', 2);
