INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_3e8b8493c59b0af1', 'course_programming_fundamentals', 'exe_9a4c42a24ac8dec4', 'After the fifth mark, `90`, the algorithm asks for **another** mark.', 1, 'Right: only the three passing marks moved `counter`, so it is 4 after the five marks. `4 <= 5` is TRUE, so the loop runs again and waits for a sixth mark.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_95cf5bea28cef381', 'course_programming_fundamentals', 'exe_9a4c42a24ac8dec4', 'Whenever the algorithm does finish, it prints `5`.', 1, 'Right: `passCount` and `counter` now always go up **together**. The loop stops when `counter` reaches 6, and at that moment `passCount` is exactly 5.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cd1d03bb94ac94f4', 'course_programming_fundamentals', 'exe_9a4c42a24ac8dec4', 'It prints `3` after the fifth mark, because three of the five marks are passes.', 0, 'It never reaches `PRINT passCount` after five marks: the two FAIL marks didn''t move `counter`, so the loop isn''t finished yet.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_406313124fc5e29f', 'course_programming_fundamentals', 'exe_9a4c42a24ac8dec4', 'It can never stop, whatever marks are typed.', 0, 'It does stop, once 5 marks of 50 or more have been typed. Each pass moves `counter` by 1, and the fifth pass makes `6 <= 5` FALSE.', 4);
