INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_ce5bea7937aa0812', 'course_programming_fundamentals', 'exe_7453abd071fc075c', '`3 20` ↵', 1, 'Right: `cin` reads 3 into `tickets`, stops at the space, then reads 20 into `price`. 3 × 20 = 60.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_8b405dc0357d14d1', 'course_programming_fundamentals', 'exe_7453abd071fc075c', '`3` ↵ `20` ↵', 1, 'Right: one `cin` can read values typed on separate lines. After the first Enter it simply waits for the second value.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d5ab9c6888a7086b', 'course_programming_fundamentals', 'exe_7453abd071fc075c', '`20 3` ↵', 1, 'It prints `Total = 60` too, but only by luck: `tickets` gets 20 and `price` gets 3, the wrong way round. 20 × 3 is also 60, so the output can''t show the mistake.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_912fccbc4872c2ca', 'course_programming_fundamentals', 'exe_7453abd071fc075c', '`320` ↵', 0, '`320` is one number with no space in it, so `tickets` gets 320 and the program keeps waiting for `price`. Nothing is printed yet.', 4);
