INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_44733a74efdc76c4', 'course_programming_fundamentals', 'exe_d43c3934b0af4673', '`x = x + 5;`', 1, 'Right: the right side is worked out first with the old value, 10 + 5 = 15, and then stored back in `x`.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cd230804dab470d1', 'course_programming_fundamentals', 'exe_d43c3934b0af4673', '`x += 5;`', 1, 'Right: `x += 5` is the short way to write `x = x + 5`. `x` becomes 15.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_84a5ed876aad4da7', 'course_programming_fundamentals', 'exe_d43c3934b0af4673', '`x =+ 5;`', 0, 'It prints `5`. The two symbols are in the wrong order: C++ reads this as `x = +5`, "store plus 5 in x". The old 10 is replaced, not added to. The short form is `+=`, with the `+` first.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4f37731e4840c53c', 'course_programming_fundamentals', 'exe_d43c3934b0af4673', '`x + 5;`', 0, 'It prints `10`. C++ works out 10 + 5, but nothing tells it to **store** the answer, so it is thrown away. Only `=` (or `+=`) changes a variable.', 4);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_96521377f01d3c36', 'course_programming_fundamentals', 'exe_d43c3934b0af4673', '`x == x + 5;`', 0, 'It prints `10`. `==` only **compares**: it asks "is 10 equal to 15?" and gets FALSE. Comparing never changes a variable.', 5);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_44733a74efdc76c4', 'course_programming_fundamentals', 'exe_d43c3934b0af4673', 'Which options contain an assignment, `=` or `+=`, that stores a value in `x`?', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_cd230804dab470d1', 'course_programming_fundamentals', 'exe_d43c3934b0af4673', 'Read `=+ 5` very slowly. Which symbol comes first?', 2);
