INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a60d2524488a31f2', 'course_programming_fundamentals', 'exe_fc6dbb210fc4d16a', '10 kg', 0, 'This one is right: `10 > 10` is FALSE, so the first `IF` does nothing. `10 > 2` is TRUE, so `price` becomes 65, the correct price for 10 kg.', 3);
