INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_f3ac8dd52424ac9e', 'course_programming_fundamentals', 'exe_fc6dbb210fc4d16a', 'Trace the plan line by line for each weight. Both `IF`s are checked every time, one after the other.', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_051465f078f262e6', 'course_programming_fundamentals', 'exe_fc6dbb210fc4d16a', 'A variable keeps only its **last** value. Which `IF` runs last?', 2);
