INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_46e91b22da7c2021', 'course_programming_fundamentals', 'exe_8dc2b1115d8bbed1', '`int count = 0, total = 0;`', 1, 'Right: one line can declare several variables, separated by commas, and each one gets its own `= 0`.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_03ac3438658b78aa', 'course_programming_fundamentals', 'exe_8dc2b1115d8bbed1', '`int count = 0; int total = count;`', 1, 'Right: `count` gets 0 first. Then the value inside `count`, 0, is copied into `total`.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a75a2feb2d6c262a', 'course_programming_fundamentals', 'exe_8dc2b1115d8bbed1', '`int count = 0, total = count;`', 1, 'Right: the names are created from left to right, so `count` already holds 0 when `total = count` copies it.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_e332a6e477c17e2a', 'course_programming_fundamentals', 'exe_8dc2b1115d8bbed1', '`int count, total = 0;`', 0, 'Not sure to print `0 0`: the `= 0` belongs only to `total`. `count` is declared with **no** value, so what it holds is unpredictable. (With warnings on, g++ says `count` is used uninitialized.)', 4);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4bb1b64ddf24b9a1', 'course_programming_fundamentals', 'exe_8dc2b1115d8bbed1', '`int count = total = 0;`', 0, 'It doesn''t compile: `total` is used before it has been declared. Here only `count` is being declared, so `total` doesn''t exist yet.', 5);
