INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_2da5637cea01c19b', 'course_programming_fundamentals', 'exe_d649158e109d8c05', '`int sum = 5;` instead of `int sum = 0;`', 1, 'Right: the accumulator starts with 5 already in it, so the total is 5 + 15 = 20.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_85723c0e45bd8195', 'course_programming_fundamentals', 'exe_d649158e109d8c05', '`i++;` moved **above** `sum += i;` inside the loop.', 1, 'Right: now `i` goes up before it is added, so the loop adds 2, 3, 4, 5 and 6: 2 + 3 + 4 + 5 + 6 = 20.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_6a8968a1651cb8c4', 'course_programming_fundamentals', 'exe_d649158e109d8c05', '`int i = 0;` instead of `int i = 1;`', 0, 'This runs one extra pass, but that pass adds 0, which changes nothing. It still prints 15, so it can''t be the bug that printed 20.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_e820b749c5bc28d1', 'course_programming_fundamentals', 'exe_d649158e109d8c05', '`while (i <= 6)` instead of `while (i <= 5)`', 0, 'This adds 6 as well: 15 + 6 = 21, not 20.', 4);
