INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_ded9a8ee0a98ff26', 'course_programming_fundamentals', 'exe_adc9a5ba18215adf', 'reference_solution', '#include <iostream>
using namespace std;
int main()
{
    int counter = 1;
    int passCount = 0;
    int mark;
    while (counter <= 5)
    {
        cin >> mark;
        if (mark >= 50)
        {
            cout << "PASS" << endl;
            passCount = passCount + 1;
        }
        else
        {
            cout << "FAIL" << endl;
        }
        counter = counter + 1;
    }
    cout << "Passed: " << passCount << endl;
    cout << "Failed: " << 5 - passCount << endl;
    return 0;
}', 1);
