INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_fdd0dbe8e849944b', 'course_programming_fundamentals', 'exe_47ecd86bed0e4ed6', '`Credit: 0`', 1, 'Right: `credit = 0` stores 0 in `credit`. The value 0 counts as FALSE, so the `else` path runs, and it prints the new value, 0.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_3372595079ec0e8f', 'course_programming_fundamentals', 'exe_47ecd86bed0e4ed6', '`Credit: 12`', 0, 'The `else` path does run, but the condition has already **stored** 0 in `credit`, replacing the 12. So 0 is printed.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_67888c8041bdfc02', 'course_programming_fundamentals', 'exe_47ecd86bed0e4ed6', '`No credit`', 0, 'That would happen if a single `=` always made the condition TRUE. It doesn''t: after storing, the condition''s value is the value stored. Here that is 0, and 0 counts as FALSE.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_0c8b62dc77fdeb13', 'course_programming_fundamentals', 'exe_47ecd86bed0e4ed6', '`No credit`, then `Credit: 0`', 0, 'Only one path of an `if … else` runs each time, never both.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_fdd0dbe8e849944b', 'course_programming_fundamentals', 'exe_47ecd86bed0e4ed6', '`=` stores and `==` compares. What does `credit = 0` do to the box `credit`?', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_3372595079ec0e8f', 'course_programming_fundamentals', 'exe_47ecd86bed0e4ed6', 'A value that isn''t 0 counts as TRUE. What does 0 count as?', 2);
