INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_86364f2502e84357', 'course_programming_fundamentals', 'exe_18cdcb5287a5d31c', 'Nothing is printed at all, not even `Start`.', 1, 'Right: the compiler stops with an error, so no machine code is made and the CPU never runs a single line, not even line 6.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_86e3e2bc8753c8bb', 'course_programming_fundamentals', 'exe_18cdcb5287a5d31c', 'The mistake is found before the program runs, while the source code is being translated into machine code.', 1, 'Right: checking the code and translating it is the compiler''s job, and it happens before the run step.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_7e28fb6a974544d9', 'course_programming_fundamentals', 'exe_18cdcb5287a5d31c', '`Start` is printed first, and then the program stops with an error when it reaches line 7.', 0, 'The CPU does not read C++ line by line. It can only run machine code, and the compiler refuses to make any while the code has an error. So line 6 never runs either.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_fa349c6be2dbb91e', 'course_programming_fundamentals', 'exe_18cdcb5287a5d31c', 'The compiler adds the missing `;` by itself, so the program prints `Start` and `Hours: 1`.', 0, 'The compiler checks and translates; it never fixes your code. It shows an error and stops, and you must add the `;` yourself.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_86364f2502e84357', 'course_programming_fundamentals', 'exe_18cdcb5287a5d31c', 'Remember the three steps: write, compile, run. Which step finds a missing `;`?', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_86e3e2bc8753c8bb', 'course_programming_fundamentals', 'exe_18cdcb5287a5d31c', 'Can the CPU run C++ source code directly?', 2);
