INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1fb629dc2b8669af', 'course_programming_fundamentals', 'exe_865dd6fa1e530f8b', '`cout << (a / b == 2);`', 1, 'Right: `9 / 4` is int / int, so it is 2 (the .25 is cut off). `2 == 2` is TRUE, printed as `1`.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_6e562d274ed47dab', 'course_programming_fundamentals', 'exe_865dd6fa1e530f8b', '`cout << (a - b * 2 == a % b);`', 1, 'Right: the left side is 9 − (4 × 2) = 1, because `*` comes before `-`. The right side is `9 % 4` = 1. `1 == 1` is TRUE.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1209bea8993631c9', 'course_programming_fundamentals', 'exe_865dd6fa1e530f8b', '`cout << (a / b == 2.25);`', 0, 'It prints `0`. `a / b` is worked out as int / int **before** the comparison, so it is 2, not 2.25. `2 == 2.25` is FALSE.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a3fc603c0e82fbc4', 'course_programming_fundamentals', 'exe_865dd6fa1e530f8b', '`cout << (a / 2 * 2 == a);`', 0, 'It prints `0`. `9 / 2` is 4 (int / int), and `4 * 2` is 8. `8 == 9` is FALSE. This comparison is TRUE only for even numbers.', 4);
