INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_40b5d5080d700795', 'course_programming_fundamentals', 'exe_fdab57569fe14d03', '`km` and `fare` should both be `float` (or `double`), because a trip can be 2.5 km and a fare can have piastres.', 1, 'Right: for 2.5 km the fare is 9 + 11.25 = 20.25 pounds. An `int` would lose the decimal part of both values.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_782205622c5e5332', 'course_programming_fundamentals', 'exe_fdab57569fe14d03', 'For a trip of 9 km, the plan prints `OK` and then `49.5`.', 1, 'Right: `*` comes before `+`, so the fare is 9 + (9 × 4.5) = 9 + 40.5 = 49.5. `49.5 > 50` is FALSE, so the ELSE path prints `OK`.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_828d83929df77a4f', 'course_programming_fundamentals', 'exe_fdab57569fe14d03', 'The line `fare ← 9 + km * 4.5` adds 9 and `km` first, so it must be rewritten as `fare ← (9 + km) * 4.5`.', 0, 'Multiplication comes before addition, so the plan already works out `km * 4.5` first and then adds the 9 pounds once. The brackets would charge 4.5 pounds for the 9 starting pounds as well.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_81dd82d1a60a3be0', 'course_programming_fundamentals', 'exe_fdab57569fe14d03', 'Pseudocode has no strict rules, so `km` and `fare` won''t need a data type when the plan is turned into C++.', 0, 'Pseudocode has no strict syntax, but C++ does: every variable must be declared with a type before it is used. That is why choosing the data types is one of the three steps.', 4);
