INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_9c1cca235693562a', 'course_programming_fundamentals', 'exe_2e0c8e1a2b1ac57d', '`shelf` holds 19.', 1, 'Right: on line 6 `shelf` got a **copy** of 12. On line 8 the right side is 12 + 7 = 19, which is stored back in `shelf`.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_120255a8ccc58498', 'course_programming_fundamentals', 'exe_2e0c8e1a2b1ac57d', 'The box called `boxes` kept its name, but its value changed from 12 to 7.', 1, 'Right: a variable''s name stays the same while the program runs; only the value inside the box changes.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b65a77d852e56b76', 'course_programming_fundamentals', 'exe_2e0c8e1a2b1ac57d', 'Line 6 joined `shelf` and `boxes` into one box, so line 7 changed `shelf` to 7 as well.', 0, 'Line 6 copies the **value** 12 into `shelf`. After that the two boxes are separate, and changing `boxes` doesn''t touch `shelf`.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_3abd79e5b2f4e976', 'course_programming_fundamentals', 'exe_2e0c8e1a2b1ac57d', '`boxes` now holds two values, the old 12 and the new 7.', 0, 'A box holds one value at a time. Line 7 **replaced** 12 with 7, and the 12 is gone.', 4);
