INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_120255a8ccc58498', 'course_programming_fundamentals', 'exe_2e0c8e1a2b1ac57d', 'When a new value is stored in a box, what happens to the old one?', 2);
