INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_6e6e7809c81077ef', 'course_programming_fundamentals', 'exe_9e74be0c3d20b117', 'The body runs 4 times, the condition is checked 5 times, and the program prints `4 1`.', 1, 'Right: `x` goes 100 → 33 → 11 → 3 → 1. That is 4 passes. The fifth check, `1 > 1`, is FALSE and stops the loop.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_eb5b0cd1fc6dfc26', 'course_programming_fundamentals', 'exe_9e74be0c3d20b117', 'The body runs 4 times, the condition is checked 4 times, and the program prints `4 1`.', 0, 'The output is right, but the condition is checked once more than the body runs: the last check is the FALSE one that ends the loop.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_997e3ca9dd7b0ebc', 'course_programming_fundamentals', 'exe_9e74be0c3d20b117', 'The body runs 5 times, the condition is checked 6 times, and the program prints `5 0`.', 0, 'When `x` is 1, the check `1 > 1` is FALSE, so there is no pass that turns 1 into 0.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d1ab5e337ee6dc42', 'course_programming_fundamentals', 'exe_9e74be0c3d20b117', 'The body runs 3 times, the condition is checked 4 times, and the program prints `3 3`.', 0, 'When `x` is 3, `3 > 1` is still TRUE, so there is one more pass: 3 / 3 = 1.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_6e6e7809c81077ef', 'course_programming_fundamentals', 'exe_9e74be0c3d20b117', '`x / 3` is int / int. Work out 100 / 3, 33 / 3 and 11 / 3 without decimals.', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_eb5b0cd1fc6dfc26', 'course_programming_fundamentals', 'exe_9e74be0c3d20b117', 'Count the checks too: one before every pass, plus the one that is FALSE.', 2);
