INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_3735bf4cf14dce91', 'course_programming_fundamentals', 'exe_3af6600c4de907e7', '`int x = 10; do { cout << x << " "; x = x + 10; } while (x <= 30);`', 1, 'Right: it prints 10, 20 and 30. After printing 30, `x` becomes 40 and `40 <= 30` is FALSE.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1857412bdecdf7d2', 'course_programming_fundamentals', 'exe_3af6600c4de907e7', '`int x = 0; do { x = x + 10; cout << x << " "; } while (x < 30);`', 1, 'Right: `x` goes up **before** printing, so it prints 10, 20, 30. After printing 30, `30 < 30` is FALSE.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_98551074def312b2', 'course_programming_fundamentals', 'exe_3af6600c4de907e7', '`int x = 10; do { cout << x << " "; x = x + 10; } while (x < 30);`', 0, 'This prints only `10 20 `. After printing 20, `x` becomes 30 and `30 < 30` is FALSE, so 30 is never printed.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_503e5d5965281cc0', 'course_programming_fundamentals', 'exe_3af6600c4de907e7', '`int x = 0; do { x = x + 10; cout << x << " "; } while (x <= 30);`', 0, 'This prints `10 20 30 40 `. After printing 30, `30 <= 30` is still TRUE, so it runs once more.', 4);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cd61f35e43cc6f11', 'course_programming_fundamentals', 'exe_3af6600c4de907e7', '`int x = 40; do { cout << x << " "; x = x + 10; } while (x <= 30);`', 0, 'This prints `40 `. A do-while always runs its body once before the first check, even when the condition is FALSE from the start.', 5);
