INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_ccc8c1a1b447e490', 'course_programming_fundamentals', 'exe_62aceb7dcd53d636', '`0 77 1 62 90`', 1, 'Right: 0 is even (`0 % 2` is 0) and a fail, 77 is odd and a pass, 1 is odd and a fail, 62 and 90 are even passes. Three passes.', 3);
