INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a84524b19ac4caca', 'course_programming_fundamentals', 'exe_536a82d88dc4f436', 'Multiply the price of one card by the number of cards, and store the result in `total`.', 1, 'Precise: it says exactly which two values to use, what to do with them, and where to keep the result.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d0bb9a149f69961f', 'course_programming_fundamentals', 'exe_536a82d88dc4f436', 'Add a reasonable service fee to the total.', 0, 'Not precise: how much is "reasonable"? A person can guess; a computer can''t. The step needs an exact amount, such as "add 2 pounds".', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_620c1ffeab974e2c', 'course_programming_fundamentals', 'exe_536a82d88dc4f436', 'If `total` is 100 or more, take 5 pounds off `total`; otherwise leave `total` as it is.', 1, 'Precise: the condition (`total >= 100`) and both paths are exact. This is a decision a computer can follow.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_8fde3d62b3d110d3', 'course_programming_fundamentals', 'exe_536a82d88dc4f436', 'Keep asking the customer for cards until they seem happy.', 0, 'Not precise: a computer can''t tell whether someone "seems happy". A loop needs an exact condition, such as "until the customer types 0".', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_a84524b19ac4caca', 'course_programming_fundamentals', 'exe_536a82d88dc4f436', 'For each step, ask: could two different people follow it and get **different** results? If yes, it is not precise.', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_d0bb9a149f69961f', 'course_programming_fundamentals', 'exe_536a82d88dc4f436', 'Think of the lecture''s recipe: "add some salt" is fine for a person, but a computer needs "add 5 grams of salt".', 2);
