INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c714e369c9c6391e', 'course_programming_fundamentals', 'exe_e08c3acd74135a11', '`Enter two numbers:` / `3 4` / `Sum: 7Product: 12`', 1, 'Right: the prompt ends with `endl`, so the typing appears on the next line. Pressing Enter moves to a new line. Line 8 has no `endl`, so `Product: 12` is printed right after `Sum: 7` on the same line.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_bd612c7d3aa4b766', 'course_programming_fundamentals', 'exe_e08c3acd74135a11', '`Enter two numbers: 3 4` / `Sum: 7Product: 12`', 0, 'The typing would appear on the prompt''s line only if the prompt had no `endl`. Here `endl` already ended that line before `cin` waited for the numbers.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_938493b54c5958fd', 'course_programming_fundamentals', 'exe_e08c3acd74135a11', '`Enter two numbers:` / `3 4` / `Sum: 7` / `Product: 12`', 0, '`cout` never starts a new line on its own. Line 8 doesn''t end with `endl`, so line 9 carries on in the same line.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_ab22a5507ba905ae', 'course_programming_fundamentals', 'exe_e08c3acd74135a11', '`Enter two numbers:` / `Sum: 7Product: 12`', 0, 'The screen also shows what the user types, as they type it. `cin` prints nothing itself, but the `3 4` the user typed stays on the screen.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_c714e369c9c6391e', 'course_programming_fundamentals', 'exe_e08c3acd74135a11', 'Remember the lecture''s OUTPUT boxes: the user''s typing appears on the screen, and Enter ends that line.', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_bd612c7d3aa4b766', 'course_programming_fundamentals', 'exe_e08c3acd74135a11', 'Look at the end of every `cout` statement: does it have `endl` or not?', 2);
