INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c440327c9e006596', 'course_programming_fundamentals', 'exe_a320665e8c238bba', 'Plan A', 1, 'Right: it takes 15 off for **each** cover with `covers * 15`. For 3 covers: 225 − 45 = 180.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c7ba2dadfd8144fc', 'course_programming_fundamentals', 'exe_a320665e8c238bba', 'Plan B', 0, 'It takes 15 pounds off only **once**, whatever the number of covers. For 3 covers it prints 225 − 15 = 210. It only works when a student buys exactly 1 cover.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_12c89b8806c51551', 'course_programming_fundamentals', 'exe_a320665e8c238bba', 'Plan C', 0, 'The steps run in order, so `price ← 75` **after** the decision replaces the 60. Students still see `Student discount` but pay 75 a cover: 225 for 3 covers.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_20bf86afa454794d', 'course_programming_fundamentals', 'exe_a320665e8c238bba', 'Plan D', 1, 'Right: `price` starts at 75 and the decision lowers it to 60 for a student, **before** the total is calculated. For 3 covers: 3 × 60 = 180.', 4);
