INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_32bb9593e3e621df', 'course_programming_fundamentals', 'exe_418b08895773cf65', 'The bug is the data type: `c` and `f` are `int`, so the decimal part of 98.6 is lost.', 1, 'True: `c * 9 / 5` is int / int, so for 37 it gives 333 / 5 = 66 instead of 66.6, and an `int` box can''t hold 98.6 anyway. Making `c` and `f` `float` (or `double`) fixes it.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d9478c70ada15401', 'course_programming_fundamentals', 'exe_418b08895773cf65', 'Adding brackets, `(c * 9 / 5) + 32`, fixes the test with 37.', 0, 'False: `*` and `/` already happen before `+`, so these brackets change nothing. The program would still print `F = 98`.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c8d78a18b809567c', 'course_programming_fundamentals', 'exe_418b08895773cf65', 'Writing `c * (9 / 5) + 32` would still give the right answers for 100, 0 and -40.', 0, 'False: now `9 / 5` is worked out first, and int / int gives 1. So 100 would give 100 × 1 + 32 = 132, not 212. Only the test with 0 would still pass.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d2596e289385b269', 'course_programming_fundamentals', 'exe_418b08895773cf65', 'A test whose correct answer is a whole number, such as 100, can never show this bug.', 1, 'True: when the exact answer has no decimal part, `c * 9 / 5` divides exactly and nothing is cut off. Only a test like 37, where the answer has a decimal part, shows the bug.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_32bb9593e3e621df', 'course_programming_fundamentals', 'exe_418b08895773cf65', 'Three tests passed. What does that tell you about the order of the operations in line 7?', 1);
