INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4146876ce7647682', 'course_programming_fundamentals', 'exe_747ac1a52adb807c', 'The customer''s phone number, such as `01001234567` → `string`', 1, 'Right: a phone number is a label made of digits, not an amount. You never add or multiply phone numbers, and an `int` would lose the first 0: reading `01001234567` into an `int` stores `1001234567`.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_82c05f08a0ba7fb5', 'course_programming_fundamentals', 'exe_747ac1a52adb807c', 'The price of a phone cover, such as `87.5` pounds → `int`', 0, 'An `int` keeps only whole numbers, so 87.5 would be stored as 87. A price with piastres needs `float` or `double`.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a7fd7d061dcd7584', 'course_programming_fundamentals', 'exe_747ac1a52adb807c', 'Whether the customer has paid → `bool`', 1, 'Right: the answer is only ever yes or no, which is `true` or `false`.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cc9e7aa0121a3fa0', 'course_programming_fundamentals', 'exe_747ac1a52adb807c', 'The number of phones the customer bought, such as `2` → `char`', 0, 'A `char` holds one character, such as `''A''`. A count is a whole number that you calculate with, so it needs an `int`.', 4);
