INSERT INTO exercise_test_cases (id, course_id, exercise_id, name, stdin, expected_stdout, compare_mode, is_hidden, sort_order) VALUES ('tst_de3d817a3e6a2a46', 'course_programming_fundamentals', 'exe_8288b6f350229fa6', 'credit 15, recharge 50', '15 50
