INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_10708a1670484b0d', 'course_programming_fundamentals', 'exe_cf05b9aa35e3e1a7', '5, 6, 8, 9, 6, 8, 9, 6, 11', 1, 'Right: the initialization runs once, then the condition (line 6) is checked before every pass: TRUE for 3, TRUE for 4, and FALSE for 5. After the third check the program continues after the `}` with line 11.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_054fdef4b0ff83b3', 'course_programming_fundamentals', 'exe_cf05b9aa35e3e1a7', '5, 6, 8, 9, 8, 9, 11', 0, 'This checks the condition only once. A `while` loop checks it again before **every** pass, so line 6 must appear between the passes and once more at the end.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_7366f2e238ae9993', 'course_programming_fundamentals', 'exe_cf05b9aa35e3e1a7', '5, 6, 8, 9, 5, 6, 8, 9, 6, 11', 0, 'After the body, the program jumps back to the **condition** (line 6), not to line 5. The initialization `int count = 3;` runs only once; otherwise `count` would go back to 3 and the loop would never end.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_41c5eeb9e342b19b', 'course_programming_fundamentals', 'exe_cf05b9aa35e3e1a7', '5, 6, 8, 9, 6, 8, 9, 11', 0, 'This misses the last check. After the second pass `count` is 5, and the loop can only stop by checking `5 <= 4` on line 6 and finding it FALSE.', 4);
