INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_054fdef4b0ff83b3', 'course_programming_fundamentals', 'exe_cf05b9aa35e3e1a7', 'Where does the flow go after line 9: to line 5, or to line 6?', 2);
