INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_40c72b4daa2a9fc9', 'course_programming_fundamentals', 'exe_88c7567d9407b07e', 'reference_solution', '#include <iostream>
