INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cf8149704a777d9a', 'course_programming_fundamentals', 'exe_7535b8eb1f0bf102', 'oval Start → rectangle Input price, quantity → rectangle total ← price * quantity → rectangle Print total → oval End', 0, 'Input and output go in parallelograms, not rectangles. Only the calculation is a rectangle.', 2);
