INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_41eaf69463295fe6', 'course_programming_fundamentals', 'exe_7535b8eb1f0bf102', 'oval Start → parallelogram Input price, quantity → parallelogram Print total → rectangle total ← price * quantity → oval End', 0, 'The shapes are right, but the order is wrong: this prints `total` before it is calculated.', 4);
