INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_fb8a3efa73522039', 'course_programming_fundamentals', 'top_e07719c8d778f2a7', 'les_e07719c8d778f2a7', 'flow-shape-for-printing', 'mcq', 'The shape for printing a result', 'You are drawing the flowchart for "read a price and a quantity, and print the total cost". Which shape do you use for the step **Print total**?', NULL, NULL, '', 'Each flowchart shape has one meaning: the **oval** starts and ends the chart, the **parallelogram** is for input and output, the **rectangle** is for a calculation, and the **diamond** is for a decision.

"Print total" shows a value to the user, so it is **output** and goes in a parallelogram, just like "Print Area" in the rectangle-area flowchart. Putting it in a rectangle is a common mistake: rectangles are only for calculations.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
