INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_574ed06ce28a3a1d', 'course_programming_fundamentals', 'exe_fb8a3efa73522039', 'A parallelogram', 1, 'Right: printing is output, and input and output both go in a parallelogram.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_da5ff90b602d7484', 'course_programming_fundamentals', 'exe_fb8a3efa73522039', 'A rectangle', 0, 'Rectangles are for calculations (processing), such as `total ← price * quantity`. Printing is output, not a calculation.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_c5212ef5cb27b4a3', 'course_programming_fundamentals', 'exe_fb8a3efa73522039', 'A diamond', 0, 'A diamond is a decision: a question with two exits, YES and NO. Printing asks no question.', 3);
