INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_8e3ca417d8d6e415', '/courses/programming-fundamentals/exercises/flow-trace-pass-with-bonus', 'A bonus and a decision', 'This flowchart adds a bonus to a mark and then has a diamond , mark = 50? , with a YES exit and a NO exit. Its shapes are written below as pseudocode, one shape per step. Follow the arrows from Start to End. What exactly does it print? Type one line of output per line. BEGIN mark ← 45 bonus ← 5 mark ← mark + bonus IF mark >= 50 THEN PRINT "Pass" ELSE PRINT "Fail" END IF PRINT mark END');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_3f24fb6ec36c3248', 'course_programming_fundamentals', 'top_e07719c8d778f2a7', 'les_e07719c8d778f2a7', 'flow-which-needs-a-decision', 'mcq', 'Which flowchart needs a diamond?', 'You draw a flowchart for each problem below. Which flowchart **needs a diamond** (a decision)?', NULL, NULL, '', 'A straight-line algorithm runs every step once, top to bottom: input, calculation, output. The area, the average and the minutes-to-hours problems are all like that, so their flowcharts need only parallelograms and rectangles between Start and End.

The Pass/Fail problem is different. After reading the mark, it must check a condition, "is the mark at least 50?", and then follow **one of two paths**. That check is a decision, and a decision is drawn as a diamond with a YES exit and a NO exit.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
