INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_9d449b46acf6e0dd', 'course_programming_fundamentals', 'exe_d26a2e0aad67828f', 'After each pass of the body, just before the condition is checked again.', 1, 'Right: the order is initialization, condition, body, update, then back to the condition.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b1030bfb0b4a016b', 'course_programming_fundamentals', 'exe_d26a2e0aad67828f', 'Before each pass of the body, because it is written before the body.', 0, 'This is the most common confusion. `i++` is written first, but it runs after the body. Otherwise the first number printed would be 2.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_68a8cea6b41c6a3a', 'course_programming_fundamentals', 'exe_d26a2e0aad67828f', 'Only once, at the very start of the loop.', 0, 'That is the initialization, `int i = 1`. The update runs again after every pass.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_3f6dd198b98f0769', 'course_programming_fundamentals', 'exe_d26a2e0aad67828f', 'Only once, when the condition becomes false.', 0, 'When the condition is false, the loop simply ends. The update runs after every pass of the body.', 4);
