INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_b1030bfb0b4a016b', 'course_programming_fundamentals', 'exe_d26a2e0aad67828f', 'The three parts run at different times: once, before each pass, after each pass.', 2);
