INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_fa668f22d9906b20', 'course_programming_fundamentals', 'exe_6d5b80f2ae6d6b18', '`Cold`, then `temp is 20`', 0, 'This is what `temp == 40` would print. But the condition has only one `=`.', 1);
