INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a06a2abce9b43f0d', 'course_programming_fundamentals', 'exe_6d5b80f2ae6d6b18', '`Hot`, then `temp is 20`', 0, '`Hot` is right, but `temp = 40` also changed the value in the box. It is 40 now.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b32d9ce251102c5e', 'course_programming_fundamentals', 'exe_6d5b80f2ae6d6b18', '`Cold`, then `temp is 40`', 0, '`temp` is now 40, which is not 0, so the condition counts as TRUE and the ELSE path is skipped.', 4);
