INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_0a5c665c469d0e5b', 'course_programming_fundamentals', 'exe_6d5b80f2ae6d6b18', 'After line 6, what value is in `temp`? Is that value 0?', 2);
