INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a4f6634880ca7669', 'course_programming_fundamentals', 'exe_545be3023a12ce01', '`N % 2 == 0`', 1, 'Right: `%` gives the remainder after dividing by 2. No remainder means every item has a partner, so N is even.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a10fa818a57b1a86', 'course_programming_fundamentals', 'exe_545be3023a12ce01', '`N / 2 == 0`', 0, '`/` gives the result of the division, not the remainder. For N = 8, `8 / 2` is 4, so 8 would print ODD.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_6774e5167c1a5ca8', 'course_programming_fundamentals', 'exe_545be3023a12ce01', '`N % 2 = 0`', 0, 'One `=` stores a value; it does not compare. A condition needs `==`.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_e6f2e47607f05ef8', 'course_programming_fundamentals', 'exe_545be3023a12ce01', '`N % 2 == 1`', 0, 'This is TRUE for odd numbers, so the two paths would be swapped: 7 would print EVEN.', 4);
