INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_545be3023a12ce01', '/courses/programming-fundamentals/exercises/if-even-condition', 'The condition for an even number', 'A program reads an integer N . It should print EVEN when N is even and ODD otherwise: IF THEN PRINT "EVEN" ELSE PRINT "ODD" END IF Which condition goes in the blank?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_f326b88a2260d7a2', 'course_programming_fundamentals', 'top_d06bd9ff15d1e6cd', 'les_810ecce8c9e38678', 'if-larger-number-fix', 'correct_code', 'Fix the larger number', 'This program should read two numbers A and B and print the **larger** one. For `17 42` it prints `Larger: 17`, which is wrong. Find the bug and fix it.', '#include <iostream>
using namespace std;
int main()
{
    int A, B;
    cin >> A >> B;
    if (A < B)
    {
        cout << "Larger: " << A << endl;
    }
    else
    {
        cout << "Larger: " << B << endl;
    }
    return 0;
}', 'cpp', 'The user types two whole numbers. The program prints `Larger: ` followed by the larger of the two. For `17 42` it prints `Larger: 42`. When both numbers are equal, it prints that number.', 'The TRUE path prints `A`, so the condition must be TRUE exactly when **A is the larger number**: `A > B`. The broken condition `A < B` is TRUE when A is the **smaller** one, so the program always printed the smaller number.

With `A > B`: for 17 and 42, `17 > 42` is FALSE, so B (42) is printed. For 9 and 9, `9 > 9` is FALSE and B is printed, which is still correct because both values are equal. You could also keep `A < B` and swap what the two paths print; both fixes give the same results.', 'easy', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
