INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_63deb521c5e43c4f', '/courses/programming-fundamentals/exercises/if-price-boundary-pseudocode', 'A price on the boundary', 'Trace this pseudocode by hand. What exactly does it print? Type one value per line. BEGIN price ← 120 IF price >= 100 THEN price ← price - 20 ELSE price ← price + 10 END IF PRINT price IF price >= 100 THEN PRINT "EXPENSIVE" ELSE PRINT "CHEAP" END IF END');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_b708222d9636c93a', 'course_programming_fundamentals', 'top_d06bd9ff15d1e6cd', 'les_810ecce8c9e38678', 'if-remainder-twice', 'trace', 'Two decisions with the remainder', 'This program makes the same decision twice, with a different value of `x`. Trace it by hand. What exactly does it print? Type one line of output per line.', '#include <iostream>
using namespace std;
int main()
{
    int x = 17;
    int y = 4;
    if (x % y == 0)
    {
        cout << "divides" << endl;
    }
    else
    {
        cout << "remainder " << x % y << endl;
    }
    x = x + 3;
    if (x % y == 0)
    {
        cout << "divides" << endl;
    }
    else
    {
        cout << "remainder " << x % y << endl;
    }
    cout << "x is " << x << endl;
    return 0;
}', 'cpp', '', 'Each `if … else` chooses **one** of its two paths, and only that path runs.

- First decision: 4 fits into 17 four times (16), and 1 is left over. So `17 % 4` is 1, the condition `1 == 0` is FALSE, and the ELSE path prints `remainder 1`.
- Line 15 stores 20 in `x`.
- Second decision: `20 % 4` is 0 (4 fits exactly 5 times), so the condition is TRUE and `divides` is printed.

The two decisions look the same, but they give different results because the value of `x` changed between them. A condition always uses the value the variable has **at that moment**.', 'medium', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
