INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_b708222d9636c93a', '/courses/programming-fundamentals/exercises/if-remainder-twice', 'Two decisions with the remainder', 'This program makes the same decision twice, with a different value of x . Trace it by hand. What exactly does it print? Type one line of output per line. #include <iostream> using namespace std; int main() { int x = 17; int y = 4; if (x % y == 0) { cout << "divides" << endl; } else { cout << "remainder " << x % y << endl; } x = x + 3; if (x % y == 0) { cout << "divides" << endl; } else { cout << "remainder " << x % y << endl; } cout << "x is " << x << endl; return 0; }');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_65d1b7e8c64bdff5', 'course_programming_fundamentals', 'top_3087c084dc60a631', 'les_de9e9c05688ce607', 'intro-compiler-job', 'mcq', 'What the compiler does', 'You have written a C++ program in a file called `main.cpp`. Why does it need a **compiler** before the CPU can run it?', NULL, NULL, '', 'The C++ text you type is called the **source code**. The CPU can''t read C++; it only understands **machine code**, which is very simple instructions stored as numbers.

The **compiler** is the program that checks your source code and translates it into machine code. If it finds something wrong, it stops and shows an error instead. Only after this translation can the CPU **run** the instructions, one after another.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
