INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_97c62ff96993fa3e', 'course_programming_fundamentals', 'exe_65d1b7e8c64bdff5', 'The compiler makes the program run faster by removing the slow lines.', 0, 'The compiler does not remove lines. Its job is to translate the code.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_efa4a1c73d30919a', 'course_programming_fundamentals', 'exe_65d1b7e8c64bdff5', 'The compiler prints the output of the program on the screen.', 0, 'Printing happens when the program **runs**. The compiler works before that.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_95d701cc0473aed6', 'course_programming_fundamentals', 'exe_65d1b7e8c64bdff5', 'The CPU only understands machine code, so the compiler translates the C++ source code into machine code.', 1, 'Right: the CPU can''t read C++ directly. The compiler checks the code and translates it.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_0f1caac5ee093980', 'course_programming_fundamentals', 'exe_65d1b7e8c64bdff5', 'The compiler fixes all the mistakes in the program automatically.', 0, 'If something is wrong, the compiler stops and shows an error. You have to fix it yourself.', 4);
