INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_f8b7c7894c51ffbf', 'course_programming_fundamentals', 'exe_99577ee6dddf9cc0', 'Write the code → understand the problem → design the solution → test and improve', 0, 'Writing code first means writing it without a plan. You can''t plan steps for a problem you don''t understand yet.', 1);
