INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_c2b7a12705d766a6', 'course_programming_fundamentals', 'top_3087c084dc60a631', 'les_de9e9c05688ce607', 'intro-input-processing-output', 'mcq', 'Finding the processing step', 'A shop program reads the price of an item in pounds and the number of items bought. It multiplies them and shows the total cost on the screen.

Which part of this program is the **processing**?', NULL, NULL, '', 'Every program turns **input** into **output** through **processing**. Here the input is the price and the number of items, the processing is the multiplication, and the output is the total cost shown on the screen.

A good habit is to name these three parts before you plan anything. The calculation in the middle is the processing, because it changes the input into the result.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
