INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_8bc00d69a02229e1', 'course_programming_fundamentals', 'exe_c2b7a12705d766a6', 'Multiplying the price by the number of items.', 1, 'Right: processing is the work the program does on the input to get the result.', 2);
