INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_c2b7a12705d766a6', '/courses/programming-fundamentals/exercises/intro-input-processing-output', 'Finding the processing step', 'A shop program reads the price of an item in pounds and the number of items bought. It multiplies them and shows the total cost on the screen. Which part of this program is the processing ?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_955e944c6cd7e4ae', 'course_programming_fundamentals', 'top_3087c084dc60a631', 'les_de9e9c05688ce607', 'intro-trace-tea-steps', 'trace', 'Printing steps in order', 'Trace this program by hand. What exactly does it print? Type each line of output on its own line.', '#include <iostream>
using namespace std;
int main()
{
    cout << "Boil water" << endl;
    cout << "Add tea ";
    cout << "and sugar" << endl;
    cout << "Ready!" << endl;
    return 0;
}', 'cpp', '', 'A program follows its steps exactly, in the order they are written, so the lines are printed from top to bottom.

`endl` is what moves the output to a new line. Line 6 prints `Add tea ` (with a space at the end) but has no `endl`, so the next `cout` on line 7 continues on the **same** line. That is why the second line of output is `Add tea and sugar`. There are only three lines of output, not four.', 'medium', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
