INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_955e944c6cd7e4ae', '/courses/programming-fundamentals/exercises/intro-trace-tea-steps', 'Printing steps in order', 'Trace this program by hand. What exactly does it print? Type each line of output on its own line. #include <iostream> using namespace std; int main() { cout << "Boil water" << endl; cout << "Add tea "; cout << "and sugar" << endl; cout << "Ready!" << endl; return 0; }');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_104f4aade69f2983', 'course_programming_fundamentals', 'top_3087c084dc60a631', 'les_de9e9c05688ce607', 'intro-what-is-a-program', 'mcq', 'What is a program?', 'Which sentence best describes a **program**?', NULL, NULL, '', 'A **program** is a set of step-by-step instructions that a computer follows. The computer does exactly what the steps say, in the order they are written, and it never guesses what you meant.

That is why a recipe step like "add some salt" is fine for a person but not for a computer: a program needs exact steps, like "add 5 grams of salt". The CPU is the machine that runs the steps, and the output is the result they produce; neither of them is the program itself.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
