INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_0cbe8f2639aaa67f', 'course_programming_fundamentals', 'exe_104f4aade69f2983', 'A set of precise, step-by-step instructions that the computer follows exactly, in order.', 1, 'Right: a program is a list of exact steps, and the computer carries them out in the order they are written.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_305406051916a23f', 'course_programming_fundamentals', 'exe_104f4aade69f2983', 'A set of general ideas that the computer completes by guessing what you meant.', 0, 'The computer never guesses. If a step is not written down exactly, it does not happen.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_754bf3982c41931a', 'course_programming_fundamentals', 'exe_104f4aade69f2983', 'Only the output that appears on the screen.', 0, 'The output is what a program produces. The program is the list of steps that produces it.', 3);
