INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_aeb565a20d2ec741', 'course_programming_fundamentals', 'exe_917b218bc797ee07', '`cin >> age;`', 1, 'Right: `cin` reads from the keyboard, and `>>` points into `age`, the way the data flows.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_8ef56c4c89429ef6', 'course_programming_fundamentals', 'exe_917b218bc797ee07', '`cin << age;`', 0, 'The arrows point the wrong way. With `cin` you always use `>>`; `cin << age` does not compile.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cb8d36fd84ce2064', 'course_programming_fundamentals', 'exe_917b218bc797ee07', '`cout >> age;`', 0, '`cout` sends values **to the screen**. It cannot read what the user types.', 3);
