INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4a0f84f7949d3155', 'course_programming_fundamentals', 'exe_78efccf1bfc079c2', '`Welcome, Nour Ali!`', 0, 'That would need `getline(cin, name)`. `cin >>` stops reading at the first space.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_e259df9d3fc3b176', 'course_programming_fundamentals', 'exe_78efccf1bfc079c2', '`Welcome, Nour!`', 1, 'Right: `cin >> name` reads one word. It stops at the space, so `name` holds only `Nour`.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_febbd49c7972c070', 'course_programming_fundamentals', 'exe_78efccf1bfc079c2', '`Welcome, Ali!`', 0, '`cin` reads from the start of what was typed, so it gets the first word, not the last one.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d9f85b082e1d78e9', 'course_programming_fundamentals', 'exe_78efccf1bfc079c2', 'Nothing: a `string` can''t hold text the user types.', 0, 'A `string` variable can store typed text. The problem is only that `cin >>` reads one word.', 4);
