INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_1940bd2d3bd2c52b', 'course_programming_fundamentals', 'exe_8c08e5f2c90ecd70', 'reference_solution', '#include <iostream>
#include <string>
using namespace std;
int main()
{
    string fullName;
    cout << "Enter your full name: ";
    getline(cin, fullName);
    cout << "Welcome, " << fullName << "!" << endl;
    return 0;
}', 1);
