INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_07590073d0bda53b', 'course_programming_fundamentals', 'exe_4433ac704b7be960', '`bill >= 500`', 1, 'Right: "500 or more" is exactly what `>=` means, and 500 itself is included.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1d0147a34112f64d', 'course_programming_fundamentals', 'exe_4433ac704b7be960', '`bill > 499`', 1, 'Right, because `bill` is an `int`: the smallest whole number above 499 is 500. (It would be wrong for a `float` bill such as 499.5.)', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_bb6eedc2707064ea', 'course_programming_fundamentals', 'exe_4433ac704b7be960', '`bill > 500`', 0, 'Wrong at the boundary: a bill of exactly 500 gives `500 > 500`, which is false, so no discount.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_93f8fcdc4dd32ee9', 'course_programming_fundamentals', 'exe_4433ac704b7be960', '`bill == 500`', 0, 'This is true only for a bill of exactly 500. A bill of 750 would get no discount.', 4);
