INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_36e9e5d0c09dde12', 'course_programming_fundamentals', 'exe_6716e6f8b5d80f27', '`4 5`', 1, 'Right: 6 × 4 = 24, so each child gets 4, and 29 − 24 = 5 sweets are left over.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_dc3fb9268420a068', 'course_programming_fundamentals', 'exe_6716e6f8b5d80f27', '`4.83333 5`', 0, 'Both values are `int`, so `/` keeps only the whole part. There is no decimal part here.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4860d377b85f8b72', 'course_programming_fundamentals', 'exe_6716e6f8b5d80f27', '`5 4`', 0, 'The order is swapped. `/` gives the whole part (4) and `%` gives the remainder (5).', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4069ba6a6ec5a733', 'course_programming_fundamentals', 'exe_6716e6f8b5d80f27', '`4 1`', 0, '`%` is not "the decimal part". It is what is left over after taking out 4 groups of 6: 29 − 24 = 5.', 4);
