INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d1e30f8c4d7d6e3e', 'course_programming_fundamentals', 'exe_ae77da35d0bc6905', '`20 end`', 1, 'Right: the body runs once and prints 20, then `25 < 20` is false, so the loop stops.', 2);
