INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4537edb3e3edbc4a', 'course_programming_fundamentals', 'exe_81faad562a421d49', '`8`', 1, 'Right: `total / count` is `int / int`, so the result is 8. Storing 8 in a `float` doesn''t bring the .5 back.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_bccee339ef498ab0', 'course_programming_fundamentals', 'exe_81faad562a421d49', '`9`', 0, 'C++ does not round here. Whole-number division simply cuts off the decimal part.', 3);
