INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_2a3a614a04c1c20a', 'course_programming_fundamentals', 'top_5e676150e110b6d3', 'les_5e676150e110b6d3', 'ops-compare-after-update', 'mcq', 'Comparing after a change', 'What does this program print?', '#include <iostream>
using namespace std;
int main()
{
    int x = 7;
    x = x + 2;
    cout << (x != 7) << " " << (x >= 10) << " " << (x == 9) << endl;
    return 0;
}', 'cpp', '', 'Line 6 reads from right to left: take the old value of `x` (7), add 2, and store 9 back in `x`.

Then each comparison is a question with a TRUE or FALSE answer:

- `x != 7`: is 9 not equal to 7? TRUE, printed as `1`.
- `x >= 10`: is 9 greater than or equal to 10? FALSE, printed as `0`.
- `x == 9`: is 9 equal to 9? TRUE, printed as `1`.

The brackets around each comparison are needed inside `cout`.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
