INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_5973b2d459607ec4', 'course_programming_fundamentals', 'exe_2a3a614a04c1c20a', '`0 0 0`', 0, 'These are the answers for `x` = 7. But line 6 changed `x`: it is 9 when the comparisons run.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1213d49d7a0015ec', 'course_programming_fundamentals', 'exe_2a3a614a04c1c20a', '`true false true`', 0, 'The TRUE/FALSE pattern is right, but `cout` prints TRUE as `1` and FALSE as `0`.', 3);
