INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_6b9e68fc01a7b369', 'course_programming_fundamentals', 'top_5e676150e110b6d3', 'les_5e676150e110b6d3', 'ops-correct-minutes-and-seconds', 'correct_code', 'Fix the minutes and seconds', 'A song is 135 seconds long. This program should print its length in minutes and seconds, but it prints `15 minutes and 2 seconds`. Find the bug and fix the program.', '#include <iostream>
using namespace std;
int main()
{
    int totalSeconds = 135;
    int minutes = totalSeconds % 60;
    int seconds = totalSeconds / 60;
    cout << minutes << " minutes and " << seconds << " seconds" << endl;
    return 0;
}', 'cpp', 'There are 60 seconds in a minute, so 135 seconds is 2 full minutes and 15 seconds left over. The program prints `2 minutes and 15 seconds`.', 'The two operators are swapped. `/` gives the number of full groups and `%` gives the remainder:

- `135 / 60` is 2 (60 × 2 = 120), the full **minutes**.
- `135 % 60` is 15 (135 − 120 = 15), the **seconds** left over.

The broken program stores the remainder (15) in `minutes` and the whole part (2) in `seconds`. Using `/` for `minutes` and `%` for `seconds` fixes it.', 'medium', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
