INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_9d70405c8fc690e9', 'course_programming_fundamentals', 'top_5e676150e110b6d3', 'les_5e676150e110b6d3', 'ops-even-number-test', 'mcq', 'Testing for an even number', '`n` is an `int`. Which comparison is TRUE exactly when `n` is an **even** number?', NULL, NULL, '', 'A number is even when dividing it by 2 leaves **no remainder**. The `%` operator gives the remainder, so `n % 2` is 0 for even numbers and 1 for odd numbers. For example, `8 % 2` is 0 and `7 % 2` is 1.

To check the remainder you compare it with `==`, which gives TRUE or FALSE: `n % 2 == 0`. A single `=` would mean "store", which is not a question.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
