INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_e41b4148bcfd802a', 'course_programming_fundamentals', 'exe_9d70405c8fc690e9', '`n % 2 == 0`', 1, 'Right: an even number divided by 2 leaves nothing over, so the remainder is 0.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_8bab4a5aeced2375', 'course_programming_fundamentals', 'exe_9d70405c8fc690e9', '`n % 2 == 1`', 0, 'This is TRUE when 1 is left over, which means `n` is odd.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1a74d5e6c1b7573b', 'course_programming_fundamentals', 'exe_9d70405c8fc690e9', '`n / 2 == 0`', 0, '`/` gives the whole part, not the remainder. For example, `8 / 2` is 4, so this is FALSE for 8 even though 8 is even.', 3);
