INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_c73b92867f8914cd', '/courses/programming-fundamentals/exercises/ops-trace-fan-comparisons', 'Is it hotter than 30?', 'Trace the program by hand. Remember how cout prints TRUE and FALSE. What exactly does it print? Type one value per line. #include <iostream> using namespace std; int main() { int temperature = 30; cout << (temperature > 30) << endl; cout << (temperature >= 30) << endl; temperature = temperature + 1; cout << (temperature > 30) << endl; cout << (temperature != 31) << endl; return 0; }');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_5e9c5ac3c19c319f', 'course_programming_fundamentals', 'top_5e676150e110b6d3', 'les_5e676150e110b6d3', 'ops-trace-packing-eggs', 'trace', 'Packing eggs in boxes of 6', 'A farm packs 47 eggs in boxes of 6. Trace the program by hand. What exactly does it print? Type one line of output per line.', '#include <iostream>
using namespace std;
int main()
{
    int eggs = 47;
    int boxes = eggs / 6;
    int left = eggs % 6;
    cout << boxes << " " << left << endl;
    int check = boxes * 6;
    check = check + left;
    cout << check << endl;
    cout << left % 2 << endl;
    return 0;
}', 'cpp', '', '`/` and `%` work as a pair. `47 / 6` is 7 full boxes (both values are `int`, so the decimal part is cut off), and `47 % 6` is the 5 eggs left over, because 6 × 7 = 42 and 47 − 42 = 5.

Lines 9 and 10 check the answer: 7 boxes of 6 is 42 eggs, plus the 5 left over gives back 47. Line 10 reads right to left: the old `check` (42) plus 5 is stored back in `check`.

Finally, `left % 2` is `5 % 2`, which is 1, so the number of eggs left over is odd.', 'medium', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
