INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_cc7a4fea7e9479b4', 'course_programming_fundamentals', 'top_7bc76727bcec74a6', 'les_4b0a034921210e04', 'order-average-of-marks', 'correct_code', 'Put the average program in order', 'The middle lines of this program are mixed up. Move them into the right order so the program reads two marks and prints their average.', '#include <iostream>
using namespace std;
int main()
{
    // [order]
    float a, b;
    cout << "Enter two marks: ";
    cin >> a >> b;
    float average = (a + b) / 2;
    cout << "Average: " << average << endl;
    // [/order]
    return 0;
}', 'cpp', 'The program asks for two marks, reads them, and prints `Average: ` followed by their average.', 'A program runs from top to bottom, so the order follows the input, processing, output plan:

1. Declare the boxes `a` and `b` and ask for the marks. These two can swap: either order works, as long as both come before `cin`.
2. The prompt comes before reading, so the user knows what to type.
3. Read both marks with `cin`.
4. Calculate the average, now that both marks are known.
5. Print it.', 'easy', 'reference_review', '{"ask":"order","compare":"trim_trailing"}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
