INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_0417a54a06d2e6a4', 'course_programming_fundamentals', 'top_90210695d2bff4ab', 'les_b1f22f1b15df7fbf', 'pseudo-what-is-pseudocode', 'mcq', 'What is true about pseudocode?', 'Which sentence about **pseudocode** is true?', NULL, NULL, '', '**Pseudocode** is an informal way of describing an algorithm with simple, structured, English-like statements. It is not a real programming language, no computer runs it, and it has no strict syntax rules.

It sits between human thinking and real code. Because it focuses on the logic and not on language details, the same pseudocode can be turned into C++, Python or Java, and each line maps naturally to a line of code.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
