INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a18e1f1416dd6056', 'course_programming_fundamentals', 'exe_0417a54a06d2e6a4', 'It is a programming language that the computer runs after compiling it.', 0, 'No computer runs pseudocode. It is not a real programming language.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_a75dde8aac133523', 'course_programming_fundamentals', 'exe_0417a54a06d2e6a4', 'It is structured, English-like steps that people use to plan an algorithm before writing code.', 1, 'Right: pseudocode is written for people, to plan the logic first.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_34a63d169ef38b25', 'course_programming_fundamentals', 'exe_0417a54a06d2e6a4', 'It only works for C++, so a Python programmer can''t use it.', 0, 'Pseudocode is language independent: the same plan can become C++, Python, Java or any other language.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_2dc804b3e63f01d8', 'course_programming_fundamentals', 'exe_0417a54a06d2e6a4', 'Every line must end with a semicolon, or it is wrong.', 0, 'Pseudocode has no strict syntax rules. Semicolons are a C++ rule, not a pseudocode rule.', 4);
