INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_8495273336ee7654', 'course_programming_fundamentals', 'exe_af7863da53e86191', '`Average = 8`', 0, 'That is the answer we want, but the line has no brackets, so the program does not add first.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cc1d739e7f7385b8', 'course_programming_fundamentals', 'exe_af7863da53e86191', '`Average = 16`', 1, 'Right: division happens before addition, so it calculates 4 + 8 + (12 / 3) = 4 + 8 + 4 = 16.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_bf644cbd2bfa8f54', 'course_programming_fundamentals', 'exe_af7863da53e86191', '`Average = 4`', 0, '12 / 3 is 4, but the program still adds `n1` and `n2` to it.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_ddbf9326280083c7', 'course_programming_fundamentals', 'exe_af7863da53e86191', '`Average = 24`', 0, '24 is the sum. The line still divides `n3` by 3 before adding.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_8495273336ee7654', 'course_programming_fundamentals', 'exe_af7863da53e86191', 'In C++, as in maths, which happens first: `/` or `+`?', 1);
