INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_af7863da53e86191', '/courses/programming-fundamentals/exercises/solve-average-without-brackets', 'An average without brackets', 'This program should print the average of 4, 8 and 12. The correct average is 8. What does it actually print? #include <iostream> using namespace std; int main() { float n1 = 4, n2 = 8, n3 = 12; float average = n1 + n2 + n3 / 3; cout << "Average = " << average << endl; return 0; }');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_c645f8325647bd4e', 'course_programming_fundamentals', 'top_5d3151db5feee6a4', 'les_6063a88c5a315cf3', 'solve-choose-test-cases', 'mcq', 'Choosing good test cases', 'A program reads a student''s mark and prints `PASS` if the mark is 50 or more, and `FAIL` otherwise. Which set of test marks is the **best** for checking that it works?', NULL, NULL, '', 'A program that gives the right answer once is not proven correct. One test only shows it works for that one input. Good tests cover every possible output **and** the edges.

Here, 30 should print `FAIL`, 70 should print `PASS`, and 50 checks the edge: "50 or more" includes 50 itself, so it must print `PASS`. A common mistake is to write "greater than 50", which only the test with 50 can catch.', 'medium', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
