INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d16ae0f87053a4dc', 'course_programming_fundamentals', 'exe_c645f8325647bd4e', '70', 0, 'One test only shows the program works for that one mark. It never checks the `FAIL` path.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_9df0574ab9c39a65', 'course_programming_fundamentals', 'exe_c645f8325647bd4e', '70, 80, 90', 0, 'Three tests, but all of them should print `PASS`. A mistake in the `FAIL` path would not be found.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d07939013cf22f3e', 'course_programming_fundamentals', 'exe_c645f8325647bd4e', '30, 50, 70', 1, 'Right: one mark that should fail, the exact pass mark (the edge), and one mark that should pass.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_01c118d423b4ad26', 'course_programming_fundamentals', 'exe_c645f8325647bd4e', '50', 0, 'Testing the edge is good, but alone it does not check a normal pass or a normal fail.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_d16ae0f87053a4dc', 'course_programming_fundamentals', 'exe_c645f8325647bd4e', 'The program has two possible outputs. Do your tests check both?', 1);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_9df0574ab9c39a65', 'course_programming_fundamentals', 'exe_c645f8325647bd4e', 'What is the most likely place for a mistake: far from 50, or exactly at 50?', 2);
