INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_32990c675cbd501b', 'course_programming_fundamentals', 'exe_67757b4007a1802c', 'Input: 500. Processing: compare the price with 500. Output: the price.', 0, '500 is a fixed rule in the problem, not a value the program reads. And the program prints a message, not the price.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_cb9724aea3f78cf0', 'course_programming_fundamentals', 'exe_67757b4007a1802c', 'Input: the price. Processing: add 30 pounds to the price. Output: the new price.', 0, 'The problem never asks to add anything. The program only decides which message to print.', 3);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b08a09143ec84214', 'course_programming_fundamentals', 'exe_67757b4007a1802c', 'Input: `Free delivery`. Processing: read the price. Output: 500.', 0, 'The parts are mixed up. The messages are what the program prints, so they are the output.', 4);
INSERT INTO exercise_hints (id, course_id, exercise_id, hint_md, sort_order) VALUES ('hnt_2e6e6277e18f88c7', 'course_programming_fundamentals', 'exe_67757b4007a1802c', 'What does the program read? That is the input.', 1);
