INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_7452f5e6b9a0f1d9', 'course_programming_fundamentals', 'exe_e0c6850b08f362ee', 'Open the editor and start typing C++ code.', 0, 'Code comes last. Without understanding the problem, you don''t know what the code should do.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_175b5190ab2cc6b3', 'course_programming_fundamentals', 'exe_e0c6850b08f362ee', 'Read the problem carefully and find its inputs, outputs and rules.', 1, 'Right: step 1 is to understand the problem. You decide what the program must do before writing any code.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_1a147598c71d9cff', 'course_programming_fundamentals', 'exe_e0c6850b08f362ee', 'Run test cases to find the errors.', 0, 'You can only test a program after it is written. Testing is part of step 3.', 3);
