INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_e0c6850b08f362ee', '/courses/programming-fundamentals/exercises/solve-first-step', 'The first thing to do with a new problem', 'Your teacher gives you a new programming problem. Following the 3-step process from the lecture, what should you do first ?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_b80d058f40eea786', 'course_programming_fundamentals', 'top_5d3151db5feee6a4', 'les_6063a88c5a315cf3', 'solve-fix-average-temperature', 'correct_code', 'Fix the average temperature', 'This program reads the temperature on two days and should print the average temperature. We test it with `20` and `30`: we expect `Average = 25`, but it prints `Average = 35`. Find the mistake and fix it.', '#include <iostream>
using namespace std;
int main()
{
    float day1, day2;
    cin >> day1 >> day2;
    float average = day1 + day2 / 2;
    cout << "Average = " << average << endl;
    return 0;
}', 'cpp', 'The user types two temperatures. The program prints `Average = ` followed by their average. For `20 30` it prints `Average = 25`.', 'In C++, as in maths, division happens **before** addition. So `day1 + day2 / 2` is calculated as `day1 + (day2 / 2)`. For 20 and 30 that is 20 + 15 = 35, not 25. Only `day2` was divided.

The fix is to put brackets around the sum: `(day1 + day2) / 2`. Now the two temperatures are added first, and the total is divided by 2. Testing with values you can check by hand (20 and 30 should give 25) is how we found this mistake.', 'medium', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
