INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_d3a874fe8a37aba5', 'course_programming_fundamentals', 'exe_508c0db439ed0b97', 'Step 3, because you have to wait.', 0, 'Waiting is just part of the step. Every time you make tea, the water must boil, so there is no choice here.', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_f8da6cc735613c2d', 'course_programming_fundamentals', 'exe_508c0db439ed0b97', 'Step 5, because it must come after step 3.', 0, 'The order matters here (you can''t pour before the water boils), but the step itself always happens.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_b87f3ca327fc5bd1', 'course_programming_fundamentals', 'exe_508c0db439ed0b97', 'Step 7, because it only happens when the answer to "Do you want sugar?" is yes.', 1, 'Right: a decision asks a yes/no question, and the step runs only on one answer.', 3);
