INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_508c0db439ed0b97', '/courses/programming-fundamentals/exercises/solve-tea-decision-step', 'The decision in the tea algorithm', 'Here is the tea algorithm from the lecture: 1. Start. 2. Fill the kettle with water. 3. Switch the kettle on and wait until the water boils. 4. Put a tea bag in a cup. 5. Pour the hot water into the cup. 6. Wait 3 minutes, then take the tea bag out. 7. If you want sugar, add it and stir. 8. End. Which step is a decision ?');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_89146ab968b69a44', 'course_programming_fundamentals', 'top_e519989412df8f8b', 'les_1946d5476bda30c9', 'trace-countdown-by-twos', 'trace', 'Counting down in twos', 'Trace the program by hand. What exactly does it print? Type one line of output per line.', '#include <iostream>
using namespace std;
int main()
{
    int n = 7;
    while (n > 0)
    {
        cout << n << endl;
        n -= 2;
    }
    cout << "Done" << endl;
    return 0;
}', 'cpp', '', '`n -= 2` is short for `n = n - 2`, so `n` goes 7, 5, 3, 1, -1. The value -1 is never printed: the condition `n > 0` is checked **before** each pass, and it is false for -1. "Done" is printed once, after the loop.', 'easy', 'auto', '{"compare":"trim_trailing","caseSensitive":true}', 1, 'published', 0, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
