INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_19cf77728dd2dc72', '/courses/programming-fundamentals/exercises/trace-halve-or-triple', 'Halve it or triple it', 'This loop has an if / else inside it. Trace it by hand. What exactly does it print? Type one line of output per line. #include <iostream> using namespace std; int main() { int n = 6; int steps = 0; while (n != 1) { if (n % 2 == 0) { n = n / 2; } else { n = 3 * n + 1; } steps++; cout << n << endl; } cout << "Steps: " << steps << endl; return 0; }');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_777856385ad6ef3c', 'course_programming_fundamentals', 'top_a369e9ead4fd7321', 'les_a369e9ead4fd7321', 'types-bool-prints-as-number', 'mcq', 'Printing a bool', 'A program stores whether a student has paid the fees. What does it print?', '#include <iostream>
using namespace std;
int main()
{
    bool feesPaid = false;
    cout << feesPaid << endl;
    return 0;
}', 'cpp', '', 'A `bool` holds only `true` or `false`. Inside the computer, `true` is stored as `1` and `false` as `0`, and by default `cout` prints a `bool` as that number.

So `cout << feesPaid` prints `0`. The value is still `false`; only the way it is printed is a number.', 'easy', 'auto', '{"shuffle":true}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
