INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_aff1d6bb85c51c6e', 'course_programming_fundamentals', 'exe_3fe9b3bc05517705', '`string name = "Mona";`', 1, 'Correct: a `string` holds text, written in double quotes.', 2);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_616f7d1aa95137b0', 'course_programming_fundamentals', 'exe_3fe9b3bc05517705', '`char grade = "B";`', 0, 'Wrong: `"B"` in double quotes is text (a string), even though it has only one letter. A `char` needs single quotes: `''B''`. The compiler refuses this line.', 3);
