INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_e99682d4509714bd', '/courses/programming-fundamentals/exercises/types-trace-where-decimals-go', 'Where did the decimals go?', 'Trace the program by hand. Watch the type of each variable. What exactly does it print? Type one value per line. #include <iostream> using namespace std; int main() { int marks = 38.5; float average = 38.5; bool passed = false; cout << marks << endl; cout << average << endl; cout << marks / 4 << endl; cout << average / 4 << endl; cout << passed << endl; return 0; }');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_07912a64d1df6830', 'course_programming_fundamentals', 'top_a4b48227d1aff1d2', 'les_a4b48227d1aff1d2', 'value-for-total-after-loop', 'trace', 'What is total when the loop ends?', 'What is the value of `total` **right after the loop ends** (on the `cout` line)? Type just the number.', '#include <iostream>
using namespace std;
int main()
{
    int total = 0;
    for (int i = 1; i <= 7; i = i + 2)
    {
        total = total + i;
    }
    cout << "Done" << endl;
    return 0;
}', 'cpp', '', '`i` takes the values 1, 3, 5 and 7. The next value, 9, fails `i <= 7`, so the loop stops.

`total` grows like this: 0 + 1 = 1, then 1 + 3 = 4, then 4 + 5 = 9, then 9 + 7 = **16**.

The program itself only prints `Done`, so you have to trace the variable to find its value.', 'medium', 'auto', '{"ask":"value","compare":"normalize_whitespace","caseSensitive":true,"verify":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\nint main()\n{\n    int total = 0;\n    for (int i = 1; i <= 7; i = i + 2)\n    {\n        total = total + i;\n    }\n    cout << total << endl;\n    return 0;\n}"}}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
