INSERT INTO search_index (course_id, entity_type, entity_id, url, title, body) VALUES ('course_programming_fundamentals', 'exercise', 'exe_07912a64d1df6830', '/courses/programming-fundamentals/exercises/value-for-total-after-loop', 'What is total when the loop ends?', 'What is the value of total right after the loop ends (on the cout line)? Type just the number. #include <iostream> using namespace std; int main() { int total = 0; for (int i = 1; i <= 7; i = i + 2) { total = total + i; } cout << "Done" << endl; return 0; }');
INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_f4a91a617dc8136f', 'course_programming_fundamentals', 'top_d06bd9ff15d1e6cd', 'les_810ecce8c9e38678', 'value-library-fine-with-maximum', 'trace', 'What is the library fine?', 'A library charges 2 pounds a day for the first 7 days a book is late, then 5 pounds a day after that, and never more than 40 pounds in total. A book is 12 days late. What is the value of `fine` **when the program reaches `return 0;`**? Type just the number.', '#include <iostream>
using namespace std;
int main()
{
    int daysLate = 12;
    int fine;
    if (daysLate > 7)
    {
        fine = 7 * 2 + (daysLate - 7) * 5;
    }
    else
    {
        fine = daysLate * 2;
    }
    if (fine > 40)
    {
        fine = 40;
        cout << "Maximum fine" << endl;
    }
    else
    {
        cout << "Normal fine" << endl;
    }
    return 0;
}', 'cpp', '', '**First decision:** `12 > 7` is TRUE, so the TRUE path runs:

`fine = 7 * 2 + (12 - 7) * 5` = 14 + 5 × 5 = 14 + 25 = **39**.

**Second decision:** `39 > 40` is FALSE, so `fine` is **not** changed to 40. The else path prints `Normal fine`.

So `fine` is still **39** at `return 0;`. If you answered 40, you applied the maximum even though the fine is below it. If you answered 24 (12 × 2), you took the else path of the first decision, but 12 days is more than 7.', 'medium', 'auto', '{"ask":"value","compare":"normalize_whitespace","caseSensitive":true,"verify":{"language":"cpp","code":"#include <iostream>\nusing namespace std;\nint main()\n{\n    int daysLate = 12;\n    int fine;\n    if (daysLate > 7)\n    {\n        fine = 7 * 2 + (daysLate - 7) * 5;\n    }\n    else\n    {\n        fine = daysLate * 2;\n    }\n    if (fine > 40)\n    {\n        fine = 40;\n    }\n    cout << fine << endl;\n    return 0;\n}"}}', 1, 'published', 0, 1791590400000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
