INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_729a594dad7a08a9', 'course_programming_fundamentals', 'exe_f52bcc7fb6d46f66', '`marks = 20;`', 1, 'Right: the value on the right (20) goes into the variable on the left (`marks`).', 1);
INSERT INTO exercise_options (id, course_id, exercise_id, label_md, is_correct, feedback_md, sort_order) VALUES ('opt_4199fa5acc383c51', 'course_programming_fundamentals', 'exe_f52bcc7fb6d46f66', '`20 = marks;`', 0, 'This is backwards. The variable must be on the left of `=`. You can''t store anything in the number 20.', 2);
