INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_e1fa728360e00ae6', 'course_programming_fundamentals', 'exe_3461a60f58f87279', 'reference_solution', '#include <iostream>
using namespace std;
int main()
{
    int number;
    int count = 0;
    float sum = 0;
    cin >> number;
    while (number != 0)
    {
        sum += number;
        count++;
        cin >> number;
    }
    if (count == 0)
    {
        cout << "No numbers" << endl;
    }
    else
    {
        float average = sum / count;
        cout << "Count = " << count << endl;
        cout << "Average = " << average << endl;
    }
    return 0;
}', 1);
