INSERT INTO exercises (id, course_id, topic_id, lesson_id, slug, type, title, prompt_md, code, code_language, expected_behavior_md, explanation_md, difficulty, grading_mode, settings, points, status, is_demo, updated_at) VALUES ('exe_bf998e1c47e2d8f3', 'course_programming_fundamentals', 'top_e519989412df8f8b', 'les_1946d5476bda30c9', 'write-even-numbers-up-to-n', 'write_code', 'Print the even numbers up to n', 'Write a program that reads a whole number `n` and prints every even number from 2 up to `n`, one per line, using a `while` loop.', '#include <iostream>
using namespace std;
int main()
{
    int n;
    cin >> n;
    // your loop here

    return 0;
}', 'cpp', 'For `n = 9` the program prints 2, 4, 6 and 8, each on its own line. For `n = 1` it prints nothing.', 'Start at the first even number, 2, and count in steps of 2 with `even += 2`, so the loop only ever visits even numbers. The condition `even <= n` includes `n` itself when it is even (n = 10 prints 10) and stops before going past it. When `n` is 1, the condition `2 <= 1` is false at the very first check, so the body never runs and nothing is printed.

Another correct way is to count `i` from 1 to `n` and print only when `i % 2 == 0`.', 'easy', 'reference_review', '{"compare":"trim_trailing"}', 1, 'published', 0, 1791504000000) ON CONFLICT (id) DO UPDATE SET topic_id = excluded.topic_id, lesson_id = excluded.lesson_id, slug = excluded.slug, type = excluded.type, title = excluded.title, prompt_md = excluded.prompt_md, code = excluded.code, code_language = excluded.code_language, expected_behavior_md = excluded.expected_behavior_md, explanation_md = excluded.explanation_md, difficulty = excluded.difficulty, grading_mode = excluded.grading_mode, settings = excluded.settings, points = excluded.points, status = excluded.status, is_demo = excluded.is_demo, updated_at = excluded.updated_at;
