INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_ad44f35409173e3a', 'course_programming_fundamentals', 'exe_2a8427eb68968ab7', 'reference_solution', '#include <iostream>
