INSERT INTO exercise_answers (id, course_id, exercise_id, kind, value, sort_order) VALUES ('ans_c4d32f0a812b2311', 'course_programming_fundamentals', 'exe_6d699a88bcd041c6', 'reference_solution', '#include <iostream>
using namespace std;
int main()
{
    int n;
    cin >> n;
    int sum = 0;
    for (int i = 1; i <= n; i += 2)
    {
        sum += i;
    }
    cout << "Sum = " << sum << endl;
    return 0;
}', 1);
